								local isLua = type(islclosure) == "function" and islclosure(callback)
								local isExecutor = type(is_synapse_function) == "function" and is_synapse_function(callback)

								if isLua and not isExecutor then
									connection:Disable()
									table.insert(disabled, connection)
								end
							end
						end

						return disabled
					end

					getgenv().EnableFastWalk = function(walkSpeed)
						getgenv().WalkSpeed = walkSpeed

						if walkSpeed then
							if fastWalkBound then
								return
							end

							-- BINDING INFERRED: in the original, the render step closes over the hub's own locals for the character's
							-- HumanoidRootPart (pA5531 upv3 / render-step upv1) and Humanoid (render-step upv2); the hub refreshes those on
							-- CharacterAdded (final/hub_full.lua ~5307) right before it re-calls EnableFastWalk. Resolved here from the
							-- LocalPlayer character at bind time, with the same FindFirstChild lookups the hub uses.
							local character = localPlayer.Character
							local rootPart = character and character:FindFirstChild("HumanoidRootPart")
							local humanoid = character and character:FindFirstChild("Humanoid")

							if not rootPart then
								-- the original would error on rootPart.Changed here; this is a quiet equivalent, flag stays unset
								return
							end

							disableGameConnections(rootPart.Changed)
							disableGameConnections(rootPart:GetPropertyChangedSignal("CFrame"))

							RunService:BindToRenderStep("FastWalk", 1, function(dt)
								if getgenv().ForceDisableFastWalk then
									return
								end

								if not getgenv().WalkSpeed then
									return
								end

								if not rootPart or not humanoid then
									return
								end

								local step = math.min(dt, 0.016666666666666666)
								local moveDirection = humanoid.MoveDirection

								if moveDirection.Magnitude < 0.05 then
									return
								end

								local speed = tonumber(getgenv().FastWalkSpeed) or 60

								if speed <= 0 then
									return
								end

								rootPart.CFrame += moveDirection * step * speed
							end)

							fastWalkBound = true
						elseif fastWalkBound then
							RunService:UnbindFromRenderStep("FastWalk")
							fastWalkBound = false
						end
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: FarmStatusText (final/missing/FarmStatusText.lua) =====
				do
					-- FarmStatusText(key)  key = "Farm" | "Scroll" | "Haki" | "KillAura" | "NPC" | "Merchant" | "Fishing" | "Sell" | "Craft" | "Fruit" | "Tween" | "Trade" | "PvP"
					-- (the keys the hub registers through fn18(<tab>, "<key>", ...) for its Status paragraphs)
					--
					-- Dispatcher = pA2515: `local fn = table[key]; if not fn then return "off" end; local _, root, humanoid = <char parts>(); return fn(getgenv(), root, humanoid)`.
					-- Per-key bodies (one lifted proto each):
					--   Farm pA6792   Scroll pA3286   Haki pA5353   KillAura pA3749   NPC pA2934   Merchant pA11727   Fishing pA7963
					--   Sell pA5936   Craft pA11751   Fruit pA10051   Tween pA5004   Trade pA1888   PvP pA6885
					-- Every body is the lifted code with the decoy arithmetic and the anti-tamper `while true do end` branches removed.

					local Players = game:GetService("Players")
					local ReplicatedStorage = game:GetService("ReplicatedStorage")
					local localPlayer = Players.LocalPlayer -- every `upvN.Character` / `upvN.Name` on a player in these protos CONFIRMED

					local function playerGui()
						return localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
					end

					-- BINDING INFERRED: the hub's tween state table (`tbl3` at hub_full.lua line 2625: {Enabled, AtGoal, ...}). The status protos only read `.Enabled`
					-- (pA7963 upv5, pA5004 upv2, same field the hub reads as tbl3.Enabled). It is a hub-scope local and is NOT exported through getgenv(), so this
					-- snippet cannot see it. Replace this placeholder with the real table when spliced into hub scope; as written, "heading to ..." never shows.
					local tweenState = getgenv().__TensenTweenState or { Enabled = false }   -- bound to the hub tween-state table (E9a)

					-- pA7701 (dispatcher upv2): character, HumanoidRootPart, Humanoid. CONFIRMED (exact body).
					local function characterParts()
						local character = localPlayer.Character
						return character, character and character:FindFirstChild("HumanoidRootPart"), character and character:FindFirstChildOfClass("Humanoid")
					end

					-- BINDING INFERRED: `upvN(position)` distance helper (pA7963 upv6, pA5004 upv1, pA11727 upv6). No lifted body found; role is certain from the call
					-- sites (number of studs from the player, printed with %d). Missing root part -> 0 is a GUESS (the dozen similar protos disagree).
					local function distanceTo(position)
						local _, root = characterParts()
						if not root then
							return 0
						end
						return (position - root.Position).Magnitude
					end

					-- BINDING INFERRED: `upvN(value)` list normaliser used on dropdown values (pA5936 upv1, pA10051 upv1, pA11727 upv2, pA11751 upv1).
					-- Body generalised from pA4445 (same logic, there fixed to getgenv().CurrentFishBaitToCraft): table -> its string keys / string values,
					-- string -> one-element list.
					local function toList(value)
						local list = {}

						if type(value) == "table" then
							for k, v in pairs(value) do
								local item = type(k) == "string" and k or v
								if type(item) == "string" then
									table.insert(list, item)
								end
							end
						elseif type(value) == "string" then
							table.insert(list, value)
						end

						return list
					end

					-- pA2384 (INFERRED as pA3286 upv1 and pA11727 upv3): seconds -> m:ss
					local function clock(seconds)
						local total = math.max(0, math.floor(seconds))
						return string.format("%d:%02d", math.floor(total / 60), total % 60)
					end

					-- pA2576 (INFERRED as the peli getter: pA5353 upv4, pA5936 upv2, pA7963 upv2, pA11727 upv5): reads the Peli label on the HUD.
					local function getPeli()
						local gui = playerGui()
						local hud = gui and gui:FindFirstChild("HUD")
						local main = hud and hud:FindFirstChild("Main")
						local peli = main and main:FindFirstChild("Peli")
						local label = peli and peli:FindFirstChild("TextLabel")

						if not label then
							return 0
						end

						local digits = label.Text:gsub("[^%d]", "")
						return tonumber(digits) or 0
					end

					-- pA8619 (pA7963 upv1, pA6792 upv1, pA11727 upv4): the Traveling Merchant marker value, nil when the merchant is not out.
					local function getMerchantMarker()
						local compassGuider = ReplicatedStorage:FindFirstChild("CompassGuider")
						return compassGuider and compassGuider:FindFirstChild("Traveling Merchant")
					end

					-- NOT RECOVERED: the os.time() date table that anchors the merchant's 30 minute restock cycle (pA11727 upv1; the same table feeds pA4598).
					-- Without it the "next restock in ..." suffix is left out instead of inventing a phase.
					local restockAnchor = nil

					local function restockSuffix()
						if not restockAnchor then
							return nil
						end
						local elapsed = os.time(os.date("!*t")) - os.time(restockAnchor)
						return clock(1800 - elapsed % 1800)
					end

					-- pA903 (INFERRED as "player already owns Buso Haki": pA5353 upv1, pA6792 upv2; the status text there is "you already have Buso Haki").
					local function hasBusoHaki()
						local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

						if stats then
							local skills = stats:FindFirstChild("Skills")

							if skills then
								for _, name in ipairs({ "busoHaki", "BusoHaki", "buso", "Buso", "haki", "Haki", "busoshokuHaki", "BusoshokuHaki" }) do
									local skill = skills:FindFirstChild(name)

									if skill then
										skill = skill.Value == true or skill.Value == 1 or type(skill.Value) == "number" and skill.Value > 0
									end

									if skill then
										return true
									end
								end
							end

							local inner = stats:FindFirstChild("Stats")

							if inner then
								local buso = inner:FindFirstChild("Buso") or inner:FindFirstChild("buso")

								if buso then
									if buso.Value == true then
										buso = true
									elseif type(buso.Value) == "number" then
										buso = buso.Value > 0
									else
										buso = false
									end
								end

								if buso then
									return true
								end

								local mastery = inner:FindFirstChild("BusoMastery") or inner:FindFirstChild("busoMastery")

								if mastery and type(mastery.Value) == "number" and mastery.Value > 0 then
									return true
								end
							end
						end

						local character = localPlayer.Character

						if character then
							if character:FindFirstChild(localPlayer.Name .. "Buso") or character:FindFirstChild("Buso") or character:FindFirstChild("Haki") then
								return true
							end

							if character:GetAttribute("Buso") == true or character:GetAttribute("Haki") == true then
								return true
							end
						end

						local hud = playerGui() and playerGui():FindFirstChild("HUD")
						-- NOT RECOVERED: pA903 retries `upvN:FindFirstChild("HUD")` on a second, unidentified container (upv5) when the first lookup is nil.

						if not hud then
							return false
						end

						local main = hud:FindFirstChild("Main")

						if main then
							for _, descendant in ipairs(main:GetDescendants()) do
								if descendant:IsA("GuiObject") and (descendant.Name == "Buso" or descendant.Name == "busoHaki" or descendant.Name == "Haki") then
									return true
								end
							end
						end

						return false
					end

					-- pA485 (INFERRED as pA6792 upv4, "quest taken"): the quest panel is visible.
					local function questPanelOpen()
						local gui = playerGui()
						local quest = gui and gui:FindFirstChild("Quest")
						local main = quest and quest:FindFirstChild("Main")
						return main and main.Visible == true
					end

					-- BINDING INFERRED (GUESS for the details): `upvN(name)` -> mob, studs, aliveCount (pA6792 upv5), mob, studs (pA5353 upv2) and
					-- `upvN(name)` -> npc, studs (pA2934 upv1). No lifted body found. Criteria taken from pA3689 (same family): child of workspace.NPCs whose name matches,
					-- with a Humanoid at Health > 0 and a HumanoidRootPart/PrimaryPart. "Nearest" and the alive count are what the call sites print.
					local function findNearestAlive(name)
						local npcs = workspace:FindFirstChild("NPCs")
						local _, root = characterParts()
						local best, bestStuds, alive = nil, math.huge, 0

						if not npcs then
							return nil, 0, 0
						end

						for _, child in ipairs(npcs:GetChildren()) do
							if child.Name == name then
								local humanoid = child:FindFirstChildOfClass("Humanoid")
								local part = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart

								if humanoid and humanoid.Health > 0 and part then
									alive += 1
									local studs = root and (part.Position - root.Position).Magnitude or 0

									if studs < bestStuds then
										best, bestStuds = child, studs
									end
								end
							end
						end

						if not best then
							return nil, 0, 0
						end

						return best, bestStuds, alive
					end

					-- pA5777 (pA3749 upv3): reach the kill aura / tween farms need.
					local function targetRange()
						local genv = getgenv()
						local range = 15

						if genv.KillAura then
							range = math.max(tonumber(genv.KillAuraRange) or 15, 15)
						end

						local withNpc

						if genv.TweenToNPC then
							withNpc = math.max((tonumber(genv.NPCOffsetY) or 9) + 6, range)
						else
							withNpc = range
						end

						local withPlayer

						if genv.TweenToPlayer then
							withPlayer = math.max((tonumber(genv.PvPOffsetY) or 9) + 6, withNpc)
						else
							withPlayer = withNpc
						end

						return withPlayer
					end

					-- pA6443 (pA3749 upv4): the hit targets within `distance`, nearest first.
					local function targetsWithin(distance)
						local _, root = characterParts()
						local parts = {}
						local npcs = workspace:FindFirstChild("NPCs")
						local genv = getgenv()

						if npcs and root then
							for _, child in ipairs(npcs:GetChildren()) do
								local lowered = child.Name:lower()
								local selected = genv.TweenToNPC and genv.SelectedNPC and child.Name == genv.SelectedNPC

								if not (genv.KillAura and not genv.npcHasForceField(child) or selected or lowered:find("scient") or lowered:find("law") or child.Name == "Donmingo Family" or child.Name == "Fishman Karate User" or child.Name == "Yeti" or child.Name == "Crazy Wolf" or child.Name == "Juzo the Diamondback" or child.Name == "Roger" or child.Name == "Hawk Eye") then
									continue
								end

								local npcRoot = child:FindFirstChild("HumanoidRootPart")
								local humanoid = child:FindFirstChildOfClass("Humanoid")

								if npcRoot and humanoid and humanoid.Health > 0 then
									if (npcRoot.Position - root.Position).Magnitude <= distance then
										table.insert(parts, npcRoot)
									end
								end
							end
						end

						if genv.TweenToPlayer and root then
							local playerReach = math.min(distance, tonumber(genv.PvPRange) or 2000)

							for _, player in ipairs(Players:GetPlayers()) do
								if not genv.PvPSkippable(player) then
									local npcRoot = player.Character:FindFirstChild("HumanoidRootPart")

									if (npcRoot.Position - root.Position).Magnitude <= playerReach then
										table.insert(parts, npcRoot)
									end
								end
							end
						end

						if (genv.AutoFactory or genv.AutoFarmGearCyborg) and root then
							local env = workspace:FindFirstChild("Env")
							local factoryPool = env and env:FindFirstChild("FactoryPool")
							local hitbox = factoryPool and factoryPool:FindFirstChild("hitbox")
							local barrelHP = factoryPool and factoryPool:FindFirstChild("barrelHP")

							if hitbox and hitbox:IsA("BasePart") and (not barrelHP or barrelHP.Value and barrelHP.Value > 0) then
								if (hitbox.Position - root.Position).Magnitude <= 50 then
									table.insert(parts, hitbox)
								end
							end
						end

						if root and #parts > 1 then
							local origin = root.Position

							table.sort(parts, function(a, b)
								return (a.Position - origin).Magnitude < (b.Position - origin).Magnitude
							end)
						end

						return parts
					end

					-- pA1587 (pA5936 upv3, called under pcall): the SelectedFish entries that are actually in the inventory.
					local function sellableFish()
						local inventory = ReplicatedStorage:WaitForChild("Stats" .. localPlayer.Name).Inventory:WaitForChild("Inventory")

						if not inventory.Value or inventory.Value == "" then
							return {}
						end

						local ok, decoded = pcall(function()
							return game:GetService("HttpService"):JSONDecode(inventory.Value)
						end)

						if not ok or type(decoded) ~= "table" then
							return {}
						end

						local list = {}

						if not getgenv().SelectedFish then
							return list
						end

						for k, v in pairs(getgenv().SelectedFish) do
							local name = type(k) == "string" and k or v
							local amount = decoded[name]

							if amount and amount > 0 then
								table.insert(list, name)
							end
						end

						return list
					end

					-- BINDING INFERRED (pA7963 upv3, "no rod"): the player holds or carries a fishing rod. No body found. Built from pA2023 (finds a Tool whose name
					-- contains "rod" in a container) applied to the character and the Backpack, the two containers pA4346 searches with it.
					local function hasRod()
						local function findRod(container)
							if not container then
								return nil
							end
							for _, child in ipairs(container:GetChildren()) do
								if child:IsA("Tool") and string.find(child.Name:lower(), "rod") then
									return child
								end
							end
							return nil
						end

						return findRod(localPlayer.Character) ~= nil or findRod(localPlayer:FindFirstChild("Backpack")) ~= nil
					end

					-- pA11598 (pA7963 upv4): standing within FishingSpotRange (25) of the fishing spot.
					local function atFishingSpot()
						local spot = getgenv().FishingSpotCF

						if not spot then
							return true
						end

						local _, root = characterParts()

						if not root then
							return false
						end

						return (spot.Position - root.Position).Magnitude <= (getgenv().FishingSpotRange or 25)
					end

					local statusFns = {}

					-- pA6792
					statusFns.Farm = function(genv, root, humanoid)
						if not genv.autofarm then
							return "off"
						end

						local placeId = game.PlaceId

						if placeId ~= 3978370137 and placeId ~= 7465136166 then
							return "only works in First or Second Sea"
						end

						if not (humanoid and humanoid.Health > 0) then
							return "waiting to respawn"
						end

						if genv.AutoFishing then
							return "paused - Auto Fishing is on"
						end

						if genv.AutoMerchant and getMerchantMarker() and not genv.AlreadyGoToMerchant then
							return "paused - Auto Merchant is going to the merchant"
						end

						if genv.JuzoFighting or genv.UmiBossEngaged or genv.BossLootDwelling then
							return "paused - a boss fight is on"
						end

						local level = genv.Level and genv.Level() or 0 -- the lift calls the executor global `Level()` (BINDING INFERRED: getgenv().Level)
						local yetiQuest = genv.haki and placeId == 3978370137 and not hasBusoHaki()

						if yetiQuest then
							yetiQuest = genv.IsOnYetiQuest()
							yetiQuest = yetiQuest or level >= 80 and getPeli() >= 25000
						end

						if yetiQuest then
							return "paused - Auto Haki is doing the Yeti quest"
						end

						-- NOT RECOVERED: the Y threshold of this check (`root.Position.Y > <an undecoded constant>`, "heading to Fishman Island"). pA10627 reads
						-- getgenv().FishmanInsideY for the opposite test, so that field is used when it exists and the check is skipped otherwise.
						local fishmanY = genv.FishmanInsideY

						if placeId == 3978370137 and root and fishmanY and root.Position.Y > fishmanY then
							return string.format("Lv %d - heading to Fishman Island", level)
						end

						local mobName = placeId == 3978370137 and "Fishman Karate User" or "Crazy Wolf"

						if not questPanelOpen() then
							return string.format("Lv %d - going to take the quest", level)
						end

						local mob, studs, alive = findNearestAlive(mobName)

						if not mob then
							return string.format("Lv %d - waiting for %s to spawn", level, mobName)
						end

						return string.format("Lv %d - fighting %s (%d studs - %d alive)", level, mobName, studs, alive)
					end

					-- pA3286
					statusFns.Scroll = function(genv)
						if not genv.AutoWorldScroll then
							return "off"
						end

						if game.PlaceId ~= 3978370137 then
							return "only works in the First Sea"
						end

						local minLevel = genv.ScrollMinLevel or 325
						local level = genv.Level and genv.Level() or 0

						if minLevel > 0 and level < minLevel then
							return string.format("waiting for level %d - you are %d", minLevel, level)
						end

						local inBag = 0

						if genv.WorldScrollCount then
							local ok, result = pcall(genv.WorldScrollCount)

							if ok then
								inBag = result or inBag
							end
						end

						local tail = string.format(" - %d taken, %d in the bag", genv.ScrollsTaken or 0, inBag)

						if genv.GettingScroll then
							local reason = tostring(genv.ScrollBlockReason or "camping the spot")
							local campTime = genv.ScrollCampStart and clock(tick() - genv.ScrollCampStart) or nil

							if campTime then
								return reason .. " (" .. campTime .. ")" .. tail
							end

							return reason .. tail
						end

						if genv.ScrollNeeded and not genv.ScrollNeeded() then
							return "you already have a scroll" .. tail
						end

						return "getting ready to camp the scroll spot" .. tail
					end

					-- pA5353
					statusFns.Haki = function(genv)
						if not genv.haki then
							return "off"
						end

						if game.PlaceId ~= 3978370137 then
							return "only works in First Sea"
						end

						if hasBusoHaki() then
							return "done - you already have Buso Haki"
						end

						if not genv.IsOnYetiQuest() then
							local level = genv.Level and genv.Level() or 0
							local peli = getPeli()

							if level < 80 or peli < 25000 then
								return string.format("needs Lv 80 and 25k peli (Lv %d with %d peli)", level, peli)
							end

							return "going to take the Yeti quest"
						end

						local yeti, studs = findNearestAlive("Yeti")

						if not yeti then
							return "on the quest - waiting for the Yeti to spawn"
						end

						return string.format("fighting the Yeti (%d studs)", studs)
					end

					-- pA3749
					statusFns.KillAura = function(genv)
						if not genv.KillAura then
							return "off"
						end

						local range = targetRange()
						local targets = targetsWithin(range)

						if #targets == 0 then
							return string.format("no mobs within %d studs", math.floor(range))
						end

						local parent = targets[1].Parent
						return string.format("hitting %s (%d in range)", tostring(parent and parent.Name), #targets)
					end

					-- pA2934
					statusFns.NPC = function(genv, _, humanoid)
						if not genv.TweenToNPC then
							return "off"
						end

						local selected = genv.SelectedNPC

						if not selected or selected == "None" then
							return "pick an NPC first"
						end

						if genv.autofarm or genv.haki or genv.AutoJuzoBoss or genv.AutoMihawkBoss or genv.AutoRogerBoss or genv.AutoFishing or genv.AutoMerchant or genv.StartTweenIsland then
							return "paused - another farm is running"
						end

						if not (humanoid and humanoid.Health > 0) then
							return "waiting to respawn"
						end

						local npc, studs = findNearestAlive(selected)

						if not npc then
							return "waiting for " .. selected .. " to spawn"
						end

						local npcHumanoid = npc:FindFirstChildOfClass("Humanoid")
						return string.format("fighting %s (%d studs - HP %d/%d)", selected, studs, math.floor(npcHumanoid.Health), math.floor(npcHumanoid.MaxHealth))
					end

					-- pA11727
					statusFns.Merchant = function(genv)
						if not genv.AutoMerchant then
							return "off"
						end

						local restock = restockSuffix()
						local restockText = restock and (" - next restock in " .. restock) or ""
						local noItems = #toList(genv.SelectedMerchantItems) == 0 and " - no items picked" or ""

						if genv.AlreadyGoToMerchant then
							return "bought from this stock" .. restockText .. noItems
						end

						local marker = getMerchantMarker()

						if not marker then
							return "the merchant is not out" .. restockText .. noItems
						end

						if getPeli() <= 0 then
							return "the merchant is out but you have no peli"
						end

						if tick() < (genv.MerchantRetryAt or 0) then
							return string.format("last visit failed - trying again in %ds", math.ceil(genv.MerchantRetryAt - tick())) .. noItems
						end

						if genv.CraftingTrip then
							return "paused - crafting bait"
						end

						local position = marker.Value

						if typeof(position) == "CFrame" then
							position = position.Position
						end

						local studs = typeof(position) == "Vector3" and distanceTo(position) or 0

						if studs > 30 then
							return string.format("heading to the merchant (%d studs)", studs) .. noItems
						end

						return "at the merchant - buying" .. noItems
					end

					-- pA7963
					statusFns.Fishing = function(genv, _, humanoid)
						if not genv.AutoFishing then
							return "off"
						end

						if not (humanoid and humanoid.Health > 0) then
							return "waiting to respawn"
						end

						if genv.FruitHold then
							return "paused - storing fruit"
						end

						if genv.CraftingTrip then
							return "paused - crafting bait"
						end

						if genv.StoringFruit then
							return "paused - storing a fruit"
						end

						local toMerchant = genv.AutoMerchant and getMerchantMarker()

						if toMerchant then
							toMerchant = genv.MerchantReady
						end

						toMerchant = toMerchant and genv.MerchantReady()

						if toMerchant then
							toMerchant = getPeli() > 0
						end

						if toMerchant then
							return "paused - going to the merchant"
						end

						if not hasRod() then
							return "no rod - going to buy one"
						end

						local casts = string.format(" - %d casts", genv.ThrowsAccepted or 0)

						if genv.IsFishing then
							if genv.FishingReeled then
								return "reeling in a fish" .. casts
							end

							return string.format("line out %ds - waiting for a bite", math.floor(tick() - (genv.FishingCastAt or tick()))) .. casts
						end

						if not atFishingSpot() then
							local spot = genv.FishingSpotCF

							if tweenState.Enabled and spot then
								return string.format("heading to the fishing spot (%d studs)", distanceTo(spot.Position))
							end

							return "getting ready to head to the fishing spot"
						end

						return "at the spot - " .. tostring(genv.FishingBlockReason or "casting") .. casts
					end

					-- pA5936
