						if not genv.SellFish then
							return "off"
						end

						if #toList(genv.SelectedFish) == 0 then
							return "pick fish to sell first"
						end

						if getPeli() >= 1000000 then
							return "paused - peli is at the 1M cap"
						end

						local ok, result = pcall(sellableFish)

						if not ok or #result == 0 then
							return "nothing to sell right now"
						end

						return string.format("selling %d kind(s) of fish", #result)
					end

					-- pA11751
					statusFns.Craft = function(genv)
						if not genv.AutoCraftSelectedBait then
							return "off"
						end

						local baits = toList(genv.CurrentFishBaitToCraft)

						if #baits == 0 then
							return "pick a bait to craft first"
						end

						if genv.CraftingTrip then
							return "crafting at " .. tostring(genv.CraftNPCName or "the blacksmith")
						end

						local parts = {}

						for _, bait in ipairs(baits) do
							table.insert(parts, string.format("%s have %d can make %d", string.gsub(bait, " Fish Bait", ""), genv.baitCount(bait), genv.craftableCount(bait)))
						end

						local summary = table.concat(parts, " | ")

						if tick() < (genv.CraftRetryAt or 0) then
							return string.format("nothing could be made - checking again in %ds - ", math.ceil(genv.CraftRetryAt - tick())) .. summary
						end

						if genv.craftWorkPending() then
							return "ready - going to craft - " .. summary
						end

						return "waiting for enough fish - " .. summary
					end

					-- pA10051
					statusFns.Fruit = function(genv)
						if not genv.AutoStoreFruit and not genv.DropUnlistedFruit then
							return "off"
						end

						if genv.StoringFruit then
							if genv.FruitHold and not genv.FruitHoldAck then
								return "waiting for the cast to finish"
							end

							return "storing a fruit"
						end

						local text = string.format("watching the bag for %s - %d stored", genv.StoreAllFruit and "every fruit" or #toList(genv.SelectedFruitToStore) .. " picked fruit", genv.FruitsStored or 0)
