				-- ===== RECOVERED FROM PER-PROTO LIFT: NearbyNPCNames (final/missing/NearbyNPCNames.lua) =====
				do
					-- getgenv().NearbyNPCNames() -> { string }  (unique NPC names within NPCListRange studs, nearest first)
					-- Source: pool-format/batch_A11/pA3136.lua
					-- Caller: "Check Nearby NPCs" button in the Farm tab (hub_full.lua ~31634), which fills the SelectNPCDropdown with the result.
					-- Depends on getgenv().npcHasForceField(npcModel), which is NOT defined in hub_full.lua (see NearbyNPCNames.notes.md).
					local Players = game:GetService("Players")
					local localPlayer = Players.LocalPlayer -- BINDING: pA3136 upv1 (`upv1.Character`)

					getgenv().NearbyNPCNames = function()
						local names = {}
						local seen = {}
						local character = localPlayer.Character
						local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
						local npcs = workspace:FindFirstChild("NPCs")

						if not (humanoidRootPart and npcs) then
							return names
						end

						local found = {}

						for _, child in ipairs(npcs:GetChildren()) do
							local npcRoot = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart
							local humanoid = child:FindFirstChildOfClass("Humanoid") -- pA3136: FindFirstChildOfClass(upv2[80]); hub constants table [80] = "Humanoid"

							if npcRoot and humanoid and humanoid.Health > 0 and not seen[child.Name] and not getgenv().npcHasForceField(child) then
								local distance = (npcRoot.Position - humanoidRootPart.Position).Magnitude

								if distance <= (getgenv().NPCListRange or 1500) then
									seen[child.Name] = true
									table.insert(found, { name = child.Name, d = distance })
								end
							end
						end

						table.sort(found, function(a, b)
							return a.d < b.d
						end)

						for _, entry in ipairs(found) do
							table.insert(names, entry.name)
						end

						return names
					end
				end

