								row.name.Text = tostring(bind.name)
								row.name.TextColor3 = stateOn == false and textGray or white
								row.chip.BackgroundColor3 = stateOn == true and accent or trackBg
								row.key.TextColor3 = stateOn == true and cardBg or white
								row.dot.Visible = stateOn ~= nil
								row.dot.BackgroundColor3 = stateOn and dotOnColor or dotOffColor

								if stateOn ~= nil then
									anyState = true
								end

								row.holder.Visible = true
								row.holder.Position = UDim2.fromOffset(12, ROW_TOP + (i - 1) * ROW_PITCH)
								widestKey = math.max(widestKey, textWidth(text, 10, Enum.Font.GothamBold) + 12)
								widestName = math.max(widestName, textWidth(row.name.Text, 11, Enum.Font.Gotham))
							end

							for i = #keybindList + 1, #rows do
								rows[i].holder.Visible = false
							end

							for i = 1, #keybindList do
								local row = rows[i]
								row.chip.Size = UDim2.fromOffset(widestKey, 15)
								row.name.Position = UDim2.fromOffset(widestKey + 8, 0)
								row.name.Size = UDim2.new(1, -(widestKey + 8 + 0), 1, 0)
