					local CoreGui = game:GetService("CoreGui")
					local RunService = game:GetService("RunService")
					local LocalPlayer = Players.LocalPlayer

					-- defaults (CONFIRMED) ------------------------------------------------------------------------------------------
					getgenv().StreamerMode = getgenv().StreamerMode == true
					getgenv().StreamerHideMe = getgenv().StreamerHideMe ~= false
					getgenv().StreamerHideTeam = getgenv().StreamerHideTeam ~= false
					getgenv().StreamerHideAll = getgenv().StreamerHideAll == true
					getgenv().StreamerHideUserId = getgenv().StreamerHideUserId == true

					for _, key in ipairs({ "StreamerMaskMe", "StreamerMaskTeam", "StreamerMaskOther" }) do
