							end

							-- 2) straight down from above the island's top, over the pivot and over the bounding-box centre
							for _, origin in ipairs({ pivot.Position, boxCFrame.Position }) do
								local topHit, topInstance = getgenv().FloorUnder(Vector3.new(origin.X, topY, origin.Z), { Include = { island }, Drop = rayDrop })

								if topHit then
									logGround(
										topHit,
										topInstance,
										417107820,
										string.format("Nothing standable straight down from its pivot, so rayed down from Y %d over its top instead and landed on top of", math.floor(topY))
									)
									return CFrame.new(topHit + Vector3.new(0, groundRayLift, 0)), "island ground"
								end
							end
						end

						-- 3) nothing to ray against yet (island not streamed in): stand at the pivot, lifted clear of the sea if the pivot is under it
						local position = pivot.Position
						local waterSurfaceY = getgenv().waterSurfaceY

						if waterSurfaceY then
							waterSurfaceY = getgenv().waterSurfaceY()
						end

						local airHover = getgenv().IslandAirHover or 30
						local surfaceDepth = getgenv().IslandSurfaceDepth or 150
						local underSea = type(waterSurfaceY) == "number" and position.Y < waterSurfaceY + airHover and position.Y > waterSurfaceY - surfaceDepth
						local how = "its pivot, waiting for it to stream in"

						if underSea then
							position = Vector3.new(position.X, waterSurfaceY + airHover, position.Z)
							getgenv().IslandSeaLifts = (getgenv().IslandSeaLifts or 0) + 1
							how = "hovering over the sea at its pivot, waiting for it to stream in"
						end

						if getgenv().GroundRayLog ~= false and tick() - (getgenv().LastIslandStreamLog or 0) >= 1 then
							getgenv().LastIslandStreamLog = tick()

							if position.Y ~= pivot.Position.Y then
								log(string.format(
									"[TP] '%s' has not streamed in yet, and its pivot at Y %d is %d studs UNDER the sea (Y %d) - not going in the water. Hovering %d over the surface at Y %d instead, and dropping onto the island the moment it loads (x%d).",
									tostring(name),
									math.floor(pivot.Position.Y),
									math.floor(waterSurfaceY - pivot.Position.Y),
									math.floor(waterSurfaceY),
									math.floor(airHover),
									math.floor(position.Y),
									getgenv().IslandSeaLifts or 0
								))
							else
								log(string.format(
									"[TP] '%s' has not streamed in yet (no parts to ray against) - holding at its pivot at Y %d, in the air, until it loads. Not dropping: the only thing under us out here is the sea.",
									tostring(name),
									math.floor(pivot.Position.Y)
								))
							end
						end

						return CFrame.new(position), how
					end

					----------------------------------------------------------------------------------------------------------------------------------
					-- TPToIsland (pA9809, step function = pA11544)
					----------------------------------------------------------------------------------------------------------------------------------
					getgenv().TPToIsland = function(tpIsland)
						tpIsland = tpIsland or getgenv().TPIsland

						-- original: `tpIsland = upv1(tpIsland)[1]` with upv1 an unrecovered table helper; the dropdown value is a one-element list.
						-- BINDING INFERRED: plain tpIsland[1].
						if type(tpIsland) == "table" then
							tpIsland = tpIsland[1]
						end

						if not tpIsland or tpIsland == "" or tpIsland == "None" then
							getgenv().TPNotice("Pick a destination in Select Island (TP) first")
							return false
						end

						-- 1) where to go
						local fixedSpot = getgenv().tpFixedSpot(tpIsland)
						local target, how

						if fixedSpot then
							if typeof(fixedSpot) ~= "Vector3" then
								target = fixedSpot
							else
								target = CFrame.new(fixedSpot)
							end

							how = "a fixed spot, exactly"
						elseif tpIsland == "Fishman Teleporter" then
							local areaTeleporters = workspace:FindFirstChild("AreaTeleporters")
							local firstSea = areaTeleporters and areaTeleporters:FindFirstChild("FirstSea")
							local fishman = firstSea and firstSea:FindFirstChild("Fishman")
							local portalPart = fishman and fishman:FindFirstChild("Part2")

							if not (portalPart and portalPart:IsA("BasePart")) then
								portalPart = fishman and fishman:FindFirstChild("Part")
							end

							if not (portalPart and portalPart:IsA("BasePart")) then
								getgenv().TPNotice("Neither Fishman Part2 nor Part is loaded in this session")
								return false
							end

							target = portalPart.CFrame
							how = "the portal part, exactly"
						else
							target, how = resolveIslandTarget(tpIsland)
						end

						if not target then
							log(string.format("[TP] '%s' is not in workspace.Islands right now", tostring(tpIsland)))
							return false
						end

						if fixedSpot and getgenv().TPIslandLog ~= false then
							log(string.format("[TP] '%s' is a fixed spot at %s - going there exactly, no island to measure.", tostring(tpIsland), tostring(target.Position)))
						end

						if stopTween then
							pcall(stopTween)
						end

						-- 2) who is moving
						local character = getgenv().tpCharacter()
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						local rootPart = character and character:FindFirstChild("HumanoidRootPart")

						if not rootPart or not rootPart.Parent then
							getgenv().TPNotice("Your character is not ready to teleport yet")
							return false
						end

						-- 3) island ground-drop: only for a real island (not a fixed spot / the Fishman portal), unless IslandDropToGround == false
						local islands = workspace:FindFirstChild("Islands")
						local islandInstance = islands and islands:FindFirstChild(tpIsland) or nil
						local dropToGround = islandInstance ~= nil and not fixedSpot

						if dropToGround then
							dropToGround = tpIsland ~= "Fishman Teleporter"
						end

						-- BINDING INFERRED: the lift shows `if flag2 then local flag3 = getgenv().IslandDropToGround ~= false end` with the
						-- assignment back into flag2 lost (same shape as the Fishman line just above it).
						if dropToGround then
							dropToGround = getgenv().IslandDropToGround ~= false
						end

						-- one frame of teleporting (pA11544)
						local function step()
							-- until the island has produced real ground, keep re-resolving the target every frame (streaming)
							if dropToGround and how ~= "island ground" then
								local newTarget, newHow = resolveIslandTarget(tpIsland)

								if newTarget then
									target = newTarget
									how = newHow
								end
							end

							local ok, err = pcall(function()
								rootPart.CFrame = target
								rootPart.AssemblyLinearVelocity = Vector3.zero
								rootPart.AssemblyAngularVelocity = Vector3.zero
							end)

							if not ok then
								getgenv().TPNotice("Move failed: " .. tostring(err))
								return false
							end

							if dropToGround and how == "island ground" then
								local dropped = getgenv().DropToGround(character, nil, { Include = { islandInstance } })

								if dropped then
									target = dropped
								end
							end

							return true
						end

						-- 4) hold the spot, reset, hold again
						if not getgenv().LoopIslandTP(character, humanoid, rootPart, step) then
							return false
						end

						getgenv().TPIslandTrips = (getgenv().TPIslandTrips or 0) + 1

						if getgenv().TPIslandLog ~= false then
							log(string.format(
								"[TP] '%s' -> %s (%s) | health %s | x%d",
								tostring(tpIsland),
								tostring(target.Position),
								tostring(how or "?"),
								string.format("reset after %.2fs of repeated teleporting, then held %.2fs more", getgenv().TPIslandHold or 0.38, getgenv().TPIslandHoldAfter or 0.1),
								getgenv().TPIslandTrips
							))
						end

						return true
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: TradeInfo (final/missing/TradeInfo.lua) =====
				do
					-- getgenv().TradeInfo() -> string
					-- Source: pool-format/batch_A11/pA11767.lua   (the "Show Trade Status" button, hub_full.lua ~33267, calls it and ignores the result)
					-- Prints and returns a three-line summary of the Auto Trade state.
					-- The three helpers pA11767 captures as upvalues are lifted separately and are rebuilt here as locals so the snippet is self-contained:
					--   tradeItemNames(isMain)  = pA7823   (upv1 in pA11767)
					--   inventoryCount(item)    = pA597    (upv2 in pA11767)
					--   isMainAccount()         = pA9220   (upv3 in pA11767)
					local ReplicatedStorage = game:GetService("ReplicatedStorage")
					local HttpService = game:GetService("HttpService")
					local localPlayer = game:GetService("Players").LocalPlayer

					-- pA7823: `return upv1(v and getgenv().TradeItemMain or getgenv().TradeItemAlt or {})`
					-- BINDING INFERRED: upv1 here = the hub's local normalizeSelectedItems, which the hub also exports as getgenv().NormalizeSelectedItems.
					-- (Precedence kept exactly as lifted: when isMain is true but TradeItemMain is nil it falls through to TradeItemAlt.)
					local function tradeItemNames(isMain)
						return getgenv().NormalizeSelectedItems(isMain and getgenv().TradeItemMain or getgenv().TradeItemAlt or {})
					end

					-- pA597: number of `item` in the player's inventory JSON (ReplicatedStorage["Stats<Name>"].Inventory.Inventory.Value).
					-- BINDING: pA597 upv1 = ReplicatedStorage, upv2 = LocalPlayer, upv3 = hub constants table ([33] = 0, [68] = 1, [198] = "table").
					-- Junk anti-tamper arithmetic dropped. Same function the trade module uses for "nothing to add - no '%s' in the inventory".
					local function inventoryCount(item)
						local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

						if not stats then
							return 0
						end

						local inventory = stats:FindFirstChild("Inventory")
						local inventoryValue = inventory and inventory:FindFirstChild("Inventory")

						if not inventoryValue or not inventoryValue.Value or inventoryValue.Value == "" then
							return 0
						end

						local ok, data = pcall(function()
							return HttpService:JSONDecode(inventoryValue.Value)
						end)

						if not ok or type(data) ~= "table" then
							return 0
						end

						if data[item] ~= nil then
							if type(data[item]) == "number" then
								return data[item]
							end

							if type(data[item]) == "table" and data[item].Amount then
								return data[item].Amount
							end

							return 1
						end

						-- fallback: compare names with spaces, '-', '_' and apostrophes stripped, case-insensitive
						local wanted = string.lower((string.gsub(item, "[%s%-_']", "")))

						for key, value in pairs(data) do
							if string.lower((string.gsub(tostring(key), "[%s%-_']", ""))) == wanted then
								if type(value) == "number" then
									return value
								end

								if type(value) == "table" and value.Amount then
									return value.Amount
								end

								return 1
							end
						end

						return 0
					end

					-- pA9220: `return upv1.Name == getgenv().TradeMainAccount`  (upv1 = LocalPlayer)
					local function isMainAccount()
						return localPlayer.Name == getgenv().TradeMainAccount
					end

					getgenv().TradeInfo = function()
						local altItems = tradeItemNames(false)
						local mainItems = tradeItemNames(true)
						local altStock = {}

						for _, item in ipairs(altItems) do
							table.insert(altStock, string.format("%s x%d", item, inventoryCount(item)))
						end

						local text = string.format(
							"[Trade] %s | role: %s | trades %d, items added %d\n  alt sends: %s\n  main sends back: %s (x%d each)",
							getgenv().AutoTrade and "ON" or "OFF",
							isMainAccount() and "MAIN (receiving)" or "ALT (sending)",
							getgenv().TradesCompleted or 0,
							getgenv().TradeItemsAdded or 0,
							#altStock > 0 and table.concat(altStock, ", ") or "nothing ticked",
							#mainItems > 0 and table.concat(mainItems, ", ") or "nothing ticked",
							getgenv().TradeMainSendQty or 1
						)

						-- BINDING INFERRED: pA11767 calls `upv5(text)`; the lift does not show what upv5 is. The button's description is
						-- "Print the trade state to the console", and the hub's BMLog / BigMomPrint are no-ops in the recovered build, so plain print is used.
						print(text)

						return text
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: npcHasForceField (final/missing/npcHasForceField.lua) =====
				do
					-- getgenv().npcHasForceField(npcModel) -> boolean
					-- Sources: pool-format/batch_A11/pA238.lua (outer function with a 2 s memo) and pA8592.lua (its pcall body, also
					-- present inline in pA238). True when the NPC model carries a ForceField (trainer / safe-zone NPC):
					-- first any descendant named in getgenv().NPCForceFieldNames, otherwise a direct ForceField child.
					-- Sibling of the hub's hasVillagerForceField (hub_full.lua ~4393), which uses ForceFieldNames instead.
					local memo = setmetatable({}, { __mode = "k" }) -- BINDING INFERRED: pA238 upv1 is a table keyed by the NPC; weak keys copied from hasVillagerForceField

					getgenv().npcHasForceField = function(instance)
						if not (instance and instance.Parent) then
							return false
						end

						local cached = memo[instance]

						if cached and tick() - cached.t < 2 then
							return cached.v
						end

						-- BINDING INFERRED: pA238 ends with `memo[instance] = {t = tick(), v = false}; return false` because the lifter lost
						-- the write `flag = true` made inside the pcall body (pA8592 stores `upv2 = true`). The result variable is a local that starts false.
						local hasForceField = false

						pcall(function()
							local forceFieldNames = getgenv().NPCForceFieldNames or {}

							for _, forceFieldName in ipairs(forceFieldNames) do
								if instance:FindFirstChild(forceFieldName, true) then
									hasForceField = true
									return
								end
							end

							hasForceField = instance:FindFirstChildOfClass("ForceField") ~= nil
						end)

						memo[instance] = { t = tick(), v = hasForceField }
						return hasForceField
					end
				end

