									end

									if umiBossEngaged() or juzoUp() or getgenv().BossLootDwelling then
										-- a boss fight / loot dwell is running: stay out of its way
										waitUntil(function()
											return not ((umiBossEngaged() or juzoUp() or getgenv().BossLootDwelling) and alive() and getgenv().autofarm)
										end, 0.1)

										if not alive() or not getgenv().autofarm then
											continue
										end
									end

									local factory = (getgenv().AutoFactory or getgenv().AutoFarmGearCyborg) and game.PlaceId == SECOND_SEA

									if factory and call("FactoryPending") then
										waitUntil(function()
											return not ((getgenv().AutoFactory or getgenv().AutoFarmGearCyborg) and call("FactoryPending") and alive() and getgenv().autofarm)
										end, 0.1)

										if not alive() or not getgenv().autofarm then
											continue
										end
									end

									local myLevel = level()

									if not myLevel then
										continue
									end

									local hasHaki = call("hasBusoHaki")
									local onYetiQuest = call("IsOnYetiQuest")

									if getgenv().haki and game.PlaceId == FIRST_SEA and not hasHaki and (onYetiQuest or myLevel >= 80 and peli() >= 25000) then
										-- the haki quest takes over (First Sea): hold here until Buso is owned or the toggle is switched off
										if tweenState.Enabled then
											stopNow()
											tweenState.Enabled = false
										end

										repeat
											task.wait(0.1)
											hasHaki = call("hasBusoHaki")
										until not (getgenv().haki and alive() and not hasHaki) or stale()

										if alive() and getgenv().autofarm then
											stopNow()
											call("releaseAimStance")
											task.wait(0.5)
										end

										continue
									end

									call("FarmPreStep")

									if game.PlaceId == FIRST_SEA then
										local npcs = workspace:FindFirstChild("NPCs")

										if not npcs then
											continue
										end

										local islands = workspace:FindFirstChild("Islands")
										local fishmanIsland = islands and islands:FindFirstChild("Fishman Island")

										if not fishmanIsland then
											continue
										end

										local building = fishmanIsland:FindFirstChild("Building")
										local far = false

										if building and (humanoidRootPart.Position - building:GetPivot().Position).Magnitude > 2000 then
											far = true
										end

										if not building or far then
											-- not at Fishman Island yet: fly there, wait for the island to load in, set the spawn
											if not getgenv().autofarm then
												continue
											end

											call("TweenToFishManIsland")

											waitUntil(function()
												return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
											end)

											if not getgenv().autofarm or not alive() then
												continue
											end

											repeat
												task.wait(0.2)

												if not getgenv().autofarm or not alive() then
													stopNow()
													tweenState.Enabled = false
													break
												end
											until fishmanIsland:FindFirstChild("Building") or stale()

											if not (getgenv().autofarm and alive()) then
												continue
											end

											call("TweenFishmanSetSpawn")

											waitUntil(function()
												return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
											end, 0.5)

											task.wait(3)

											if getgenv().autofarm and alive() then
												chat()
												task.wait(1.5)

												if not stale() then
													remotes():WaitForChild("SetSpawn"):FireServer()
												end

												task.wait(1)
											end
										else
											local questVisible = questMainVisible()

											if myLevel >= 190 and questVisible == false then
												tweenState.Enabled = false
												call("TweenToBecky")

												waitUntil(function()
													return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
												end, 0.1)

												if not getgenv().autofarm or not alive() then
													continue
												end

												chat()
												task.wait(0.5)
												takeQuest("Help becky")
												task.wait(0.5)
											end

											if npcs:FindFirstChild("Fishman Karate User") then
												call("TweenToMob", {
													MobName = "Fishman Karate User",
													Speed = getgenv().TweenSpeedMaster or 70,
													Offset = Vector3.new(0, 9, 0),
													Container = npcs
												})

												continue
											end

											if tweenState.Enabled == true then
												stopNow()
												tweenState.Enabled = false
											end

											task.wait(0.5)
											call("TweenToSP")
											local retryAt = tick()

											repeat
												task.wait(0.5)

												if not tweenState.Enabled and not npcs:FindFirstChild("Fishman Karate User") and tick() - retryAt >= (getgenv().FarmSpRetry or 3) then
													retryAt = tick()
													call("TweenToSP")
												end
											until not (not npcs:FindFirstChild("Fishman Karate User") and getgenv().autofarm and alive()) or stale()

											if tweenState.Enabled then
												stopNow()
												tweenState.Enabled = false
											end
										end
									else
										if game.PlaceId ~= SECOND_SEA then
											continue
										end

										local npcs = workspace:FindFirstChild("NPCs")

										if not npcs then
											continue
										end

										if questMainVisible() == false then
											-- no quest: walk to PJ, talk, take "Help PJ"
											if tweenState.Enabled then
												stopNow()
												tweenState.Enabled = false
											end

											call("TweenToSP")

											waitUntil(function()
												return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
											end, 0.1)

											if not getgenv().autofarm or not alive() then
												continue
											end

											chat()
											task.wait(0.5)
											takeQuest("Help PJ")
											task.wait(0.5)
										end

										if npcs:FindFirstChild("Crazy Wolf") then
											call("TweenToMob", {
												MobName = "Crazy Wolf",
												Speed = getgenv().TweenSpeedMaster or 70,
												Offset = Vector3.new(0, 9, 0),
												Container = npcs
											})

											continue
										end

										if tweenState.Enabled == true then
											stopNow()
											tweenState.Enabled = false
										end

										task.wait(0.5)
										call("TweenToSP")
										local retryAt = tick()

										repeat
											task.wait(0.5)

											if not tweenState.Enabled and not npcs:FindFirstChild("Crazy Wolf") and tick() - retryAt >= (getgenv().FarmSpRetry or 3) then
												retryAt = tick()
												call("TweenToSP")
											end
										until not (not npcs:FindFirstChild("Crazy Wolf") and getgenv().autofarm and alive()) or stale()

										if tweenState.Enabled then
											stopNow()
											tweenState.Enabled = false
										end
									end
								end
							end
						end
					end)

					-- ===== 2. the Geppo trainer loop (pA11625) =====
					task.spawn(function()
						task.wait()

						while task.wait(0.5) do
							if stale() then
								break
							end

							if not (getgenv().GetGeppo and not getgenv().autofarm and not getgenv().haki and not getgenv().AutoFishing and not getgenv().AutoMerchant and not getgenv().Glide) then
								continue
							end

							local myLevel = call("Level") or 0
							local money = peli()

							if myLevel < 125 or money < 50000 then
								task.wait(1)
								continue
							end

							if tweenState.Enabled then
								continue
							end

							local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

							if not stats then
								continue
							end

							local skills = stats:FindFirstChild("Skills")

							if not skills then
								continue
							end

							local skyWalk = skills:FindFirstChild("skyWalk")

							if not skyWalk then
								continue
							end

							if skyWalk.Value == true then
								continue
							end

							local npcs = workspace:FindFirstChild("NPCs")
							local yi = npcs and npcs:FindFirstChild("Yi")

							if yi and yi:FindFirstChild("HumanoidRootPart") then
								ReplicatedStorage:WaitForChild("Events"):WaitForChild("learnStyle"):FireServer(unpack({"skyWalkTrainer"}))
								continue
							end

							call("TweenToGeppo")

							repeat
								task.wait(1)
							until not (tweenState.Enabled and getgenv().GetGeppo) or stale()

							if not getgenv().GetGeppo then
								stopNow()
							end
						end
					end)

					-- ===== 3. Kaitun: Second Sea once level 425 and a world scroll are in hand (pA2586) =====
					task.spawn(function()
						task.wait()
						local deadline = 0

						while task.wait(1) do
							if stale() or game.PlaceId ~= FIRST_SEA then
								break
							end

							if not (getgenv().autofarm and getgenv().AutoWorldScroll) then
								continue
							end

							-- pA2586 upv1 = the scroll count in the bag (getgenv().WorldScrollCount, the one the scroll status text reads)
							local count = 0

							if type(getgenv().WorldScrollCount) == "function" then
								local ok, result = pcall(getgenv().WorldScrollCount)

								if ok then
									count = result or 0
								end
							end

							if (call("Level") or 0) < 425 or count < 1 then
								continue
							end

							-- pA2586 upv2 (a loader test on top of the two checks above) is not recoverable; the toggles + level + scroll are the Kaitun setup text's whole condition
							if not (os.clock() < deadline) then
								deadline = os.clock() + 30
								local ok, result = pcall(function()
									getgenv().KaitunTravelSecondSea()
								end)

								if not ok then
									local logFn = getgenv().BMLog

									if type(logFn) == "function" then
										pcall(logFn, "[Kaitun] Second Sea teleport failed; retrying in 30s: " .. tostring(result))
									end
								end
							end
						end
					end)

					-- ===== 4. toggle-off watcher =====
					-- pA4334 (Auto Farm), pA6516 (Roger), pA7495 (Mihawk), pA8834 (Factory): `getgenv().<flag> = value; if not value and tween.Enabled then StopCurrentTween() end`.
					-- The hub's own toggle callbacks lost that call (their tween-state test became `nil and ...`), so the tween would keep flying after the toggle is switched off.
					task.spawn(function()
						task.wait()
						local flags = {"autofarm", "haki", "AutoFactory", "AutoFarmGearCyborg", "AutoRogerBoss", "AutoMihawkBoss", "AutoJuzoBoss", "AutoFishing", "AutoMerchant", "StartTweenIsland", "TweenToNPC", "TweenToPlayer"}
						local previous = {}

						for _, name in ipairs(flags) do
							previous[name] = getgenv()[name] and true or false
						end

						while task.wait(0.15) do
							if stale() then
								break
							end

							for _, name in ipairs(flags) do
								local now = getgenv()[name] and true or false

								if previous[name] and not now and tweenState.Enabled then
									stopNow()
								end

								previous[name] = now
							end
						end
					end)
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 30_FishmanAggro (final/missing_farm/F1/30_FishmanAggro.lua) =====
				do
					-- ===== F1 / 30_FishmanAggro : the aggro flag of the First Sea farm mobs =====
					-- pA3170: every 2 s, for each Fishman Karate User / Yeti in workspace.NPCs whose Aggro BoolValue is on and whose "LastAggro" attribute is older than 4 s,
					--         turn the flag back off (so a mob that lost its target stops counting as engaged).
					-- pA8928: the other half, getgenv().MarkMobAggro(parts): for a list of hit parts, flag the owning Fishman Karate User / Yeti (Aggro = true, LastAggro = tick()).
					--         Nothing in the lifted farm calls it by name (the caller is the hit code in the lane that owns the attack loop); it is exposed so that code can use it.
					local loops = getgenv().__TensenFarmLoops

					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end

					local token = {}
					loops["F1.Aggro"] = token
					local AGGRO_NAMES = {["Fishman Karate User"] = true, Yeti = true}

					local function MarkMobAggro(instances)
						for _, instance in ipairs(instances) do
							local parent = instance.Parent

							if parent and AGGRO_NAMES[parent.Name] then
								local aggro = parent:FindFirstChild("Aggro")

								if aggro then
									aggro.Value = true
									aggro:SetAttribute("LastAggro", tick())
								end
							end
						end
					end

					if rawget(getgenv(), "MarkMobAggro") == nil then
						getgenv().MarkMobAggro = MarkMobAggro
					end

					task.spawn(function()
						task.wait()

						while task.wait(2) do
							if loops["F1.Aggro"] ~= token then
								break
							end

							local npcs = workspace:FindFirstChild("NPCs")

							if not npcs then
								continue
							end

							for _, child in ipairs(npcs:GetChildren()) do
								if not AGGRO_NAMES[child.Name] then
									continue
								end

								local humanoid = child:FindFirstChildOfClass("Humanoid")
								local aggro = child:FindFirstChild("Aggro")

								if humanoid and aggro and aggro.Value then
									local last = aggro:GetAttribute("LastAggro") or 0

									if tick() - last > 4 then
										aggro.Value = false
									end
								end
							end
						end
					end)
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 00_Core (final/missing_farm/F2/00_Core.lua) =====
				do
					-- F2 / 00_Core: the combat primitives every farm calls through getgenv().
					-- RECOVERED FROM PER-PROTO LIFTS (see 00_Core.notes.md for the proto of every function and each binding's confidence):
					--   Char pA3907, isMeleeTool pA1084, equippedMelee pA6636, backpackMelee pA6054, equippedSword pA1061, backpackSword pA3516, weaponNow pA5791,
					--   equip routines pA2247 (WeaponType) / pA4929 (WeaponTypeBoss), dropAimStance pA957, PvPTarget pA1975, findNearestAlive pA8246,
					--   combatRange pA5777, targetsInRange pA6443, combatPaused pA1106, farmFeint pA7297 (+ targetBlocking pA4106 as the fallback).
					-- INFERRED / RECONSTRUCTED parts are marked in place.
					local Players = game:GetService("Players")
					local ReplicatedStorage = game:GetService("ReplicatedStorage")
					local LocalPlayer = Players.LocalPlayer

					local function swordFolder()
						local ok, result = pcall(function()
							return ReplicatedStorage.Modules.SwordHandle.Swords
						end)
						if ok then
							return result
						end
						return nil
					end

					-- pA3907
					getgenv().Char = function()
						local character = LocalPlayer.Character
						if character then
							return character
						end
						local character2
						repeat
							task.wait(getgenv().CharPollRate or 0.1)
							character2 = LocalPlayer.Character
						until character2
						return character2
					end

					-- pA1084: a tool counts as melee unless it is a sword, a rod, a pickaxe or an axe (attribute MeleeTool / Category override the name test)
					getgenv().isMeleeTool = function(instance)
						if not instance or not instance:IsA("Tool") then
							return false
						end
						local attribute = instance:GetAttribute("MeleeTool")
						if attribute ~= nil then
							return attribute == true
						end
						local category = instance:GetAttribute("Category")
						if category ~= nil and category ~= "Weapons" then
							return false
						end
						local name = instance.Name:lower()
						if name:find("rod") or name:find("pick") or name:find("axe") then
							return false
						end
						local ok, result = pcall(function()
							return ReplicatedStorage.Modules.SwordHandle.Swords:FindFirstChild(instance.Name) ~= nil
						end)
						if ok and result then
							return false
						end
						return true
					end

					-- pA6636: first melee tool held in the character (or any container passed in)
					getgenv().equippedMelee = function(instance)
						if not instance then
							return nil
						end
						for _, child in ipairs(instance:GetChildren()) do
							if getgenv().isMeleeTool(child) then
								return child
							end
						end
						return nil
					end

					-- pA6054: first melee tool in the Backpack
					getgenv().backpackMelee = function()
						local backpack = LocalPlayer:FindFirstChild("Backpack")
						if not backpack then
							return nil
						end
						for _, child in ipairs(backpack:GetChildren()) do
							if getgenv().isMeleeTool(child) then
								return child
							end
						end
						return nil
					end

					-- pA1061: name of the allowed sword the character holds (truthy), else nil
					getgenv().equippedSword = function(instance)
						if not instance then
							return nil
						end
						local swords = swordFolder()
						if not swords then
							return nil
						end
						for _, child in ipairs(swords:GetChildren()) do
							if instance:FindFirstChild(child.Name) and getgenv().swordNameAllowed(child.Name) then
								return child.Name
							end
						end
						return nil
					end

					-- pA3516: first allowed sword tool in the Backpack
					getgenv().backpackSword = function()
						local backpack = LocalPlayer:FindFirstChild("Backpack")
						local swords = swordFolder()
						if not backpack or not swords then
							return nil
						end
						for _, child in ipairs(backpack:GetChildren()) do
							if child:IsA("Tool") and swords:FindFirstChild(child.Name) and getgenv().swordNameAllowed(child.Name) then
								return child
							end
						end
						return nil
					end

					-- pA5791: what the character actually wields ("Sword" / "Melee"); falls back to the wanted type (PikaV2 counts as a sword). Cached for WeaponCacheTTL.
					local weaponChar = nil
					local weaponAt = 0
					local weaponClass = nil

					getgenv().weaponNow = function(wanted)
						local character = LocalPlayer.Character
						if not character then
							return wanted
						end
						local now = os.clock()
						if character ~= weaponChar or now - weaponAt > (getgenv().WeaponCacheTTL or 0.2) then
							weaponChar = character
							weaponAt = now
							if getgenv().equippedSword(character) then
								weaponClass = "Sword"
							elseif getgenv().equippedMelee(character) then
								weaponClass = "Melee"
							else
								weaponClass = nil
							end
						end
						local result = weaponClass or wanted
						if result == "PikaV2" then
							result = "Sword"
						end
						return result
					end

					-- pA2247 (farm weapon, reads WeaponType) and pA4929 (boss weapon, reads WeaponTypeBoss) are the same routine on a different setting.
					local function waitForTool(character, name)
						local deadline = os.clock() + 3 -- INFERRED: the lift waits without a limit; a deadline keeps a failed equip from hanging the caller
						repeat
							task.wait()
						until character:FindFirstChild(name) or os.clock() > deadline or not LocalPlayer.Character
							or not LocalPlayer.Character:FindFirstChild("Humanoid") or LocalPlayer.Character.Humanoid.Health <= 0
					end

					local function equipWeapon(weaponType)
						local character = getgenv().Char()
						local humanoid = character and character:FindFirstChild("Humanoid")
						if not character or not humanoid or humanoid.Health <= 0 then
							return
						end
						if not weaponType then
							weaponType = "Melee"
						end
						if weaponType == "Melee" then
							if getgenv().equippedMelee(character) then
								return
							end
							if not getgenv().backpackMelee() then
								-- no melee tool anywhere: keep a sword if one is held, else pull one from the bag
								if getgenv().equippedSword(character) then
									return
								end
								local sword = getgenv().backpackSword()
								if sword then
									pcall(function()
										humanoid:EquipTool(sword)
									end)
								end
								return
							end
							if character:FindFirstChildOfClass("Tool") then
								pcall(function()
									humanoid:UnequipTools()
								end)
								task.wait(0.15)
							end
							local melee = getgenv().backpackMelee()
							if not melee then
								return
							end
							task.wait(0.25)
							pcall(function()
								humanoid:EquipTool(melee)
							end)
							waitForTool(character, melee.Name)
							return
						end
						if weaponType == "Sword" or weaponType == "PikaV2" then
							local swords = swordFolder()
							if swords then
								for _, child in ipairs(swords:GetChildren()) do
									if character:FindFirstChild(child.Name) and getgenv().swordNameAllowed(child.Name) then
										return
									end
								end
							end
							-- RECONSTRUCTED: the lift ends here (the "no sword held" continuation is not in the proto). It mirrors the melee branch above: drop the
							-- tool in hand, wait, equip the first allowed sword from the Backpack.
							local sword = getgenv().backpackSword()
							if not sword then
								return
							end
							if character:FindFirstChildOfClass("Tool") then
								pcall(function()
									humanoid:UnequipTools()
								end)
								task.wait(0.15)
							end
							task.wait(0.25)
							pcall(function()
								humanoid:EquipTool(sword)
							end)
							waitForTool(character, sword.Name)
						end
					end

					-- INFERRED NAMES: the originals are unnamed locals of the loader main; callers in the lifts use them as `pcall(upvN)`.
					getgenv().equipFarmWeapon = function()
						return equipWeapon(getgenv().WeaponType)
					end

					getgenv().equipBossWeapon = function()
						return equipWeapon(getgenv().WeaponTypeBoss)
					end

					-- pA957 (a two-line proto that only calls releaseAimStance). INFERRED to be dropAimStance because pA2968 / pA538 call it right before every swing.
					getgenv().dropAimStance = function()
						local release = getgenv().releaseAimStance
						if release then
							return release()
						end
					end

					-- pA1106: true while the character is busy with a dodge / low-health retreat / replay; the m1 loops hold fire then.
					-- INFERRED as the `upvN()` gate of pA2968 / pA538 (a no-argument predicate called right after Char(); same flags BigMom's own gate tests).
					getgenv().combatPaused = function()
						local g = getgenv()
						return (g.EvadingBoss or g.EvadingKing or g.EvadingUlt or g.EvadingDive or g.EvadingAfterImage or g.LowHealthActive or g.LowHealthAnchored
							or g.PerchedOnBarrier or g.PerchEngaging or g.BarrierFlightActive or g.ReplayRunning) == true
					end

					-- pA1975: the player the Tween To Player farm fights.
					getgenv().PvPTarget = function()
						local character = LocalPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						if not root then
							return nil
						end
						if getgenv().PvPAutoTarget == false then
							local selected = getgenv().SelectedPlayer
							if type(selected) == "table" then
								selected = selected[1]
							end
							if not selected or selected == "None" then
								return nil
							end
							local player = Players:FindFirstChild(selected)
							if player and not getgenv().PvPSkippable(player) then
								return player
							end
							return nil
						end
						local range = tonumber(getgenv().PvPRange) or 2000
						local bestDistance = math.huge
						local best = nil
						for _, player in ipairs(Players:GetPlayers()) do
							if not getgenv().PvPSkippable(player) then
								local distance = (player.Character:FindFirstChild("HumanoidRootPart").Position - root.Position).Magnitude
								if distance <= range and distance < bestDistance then
									bestDistance = distance
									best = player
								end
							end
						end
						return best
					end

					-- pA8246: nearest living NPC of that name -> model, studs (floored), how many are alive. (Confirms the "GUESS" findNearestAlive of FarmStatusText.)
					-- Only defined when no earlier lane already provided it.
					if getgenv().findNearestAlive == nil then
						getgenv().findNearestAlive = function(name)
							local npcs = workspace:FindFirstChild("NPCs")
							local character = LocalPlayer.Character
							local root = character and character:FindFirstChild("HumanoidRootPart")
							if not (npcs and root) then
								return nil
							end
							local bestDistance = math.huge
							local alive = 0
							local best = nil
							for _, child in ipairs(npcs:GetChildren()) do
								if child.Name ~= name then
									continue
								end
								local humanoid = child:FindFirstChildOfClass("Humanoid")
								local npcRoot = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart
								if humanoid and npcRoot and humanoid.Health > 0 then
									alive += 1
									local distance = (npcRoot.Position - root.Position).Magnitude
									if distance < bestDistance then
										bestDistance = distance
										best = child
									end
								end
							end
							return best, math.floor(bestDistance), alive
						end
					end

					-- pA5777: how far the m1 loops reach. Kill Aura and the tween farms widen it (never below 15).
					getgenv().combatRange = function()
						local range = 15
						if getgenv().KillAura then
							range = math.max(tonumber(getgenv().KillAuraRange) or 15, 15)
						end
						local range2
						if getgenv().TweenToNPC then
							range2 = math.max((tonumber(getgenv().NPCOffsetY) or 9) + 6, range)
						else
							range2 = range
						end
						local range3
						if getgenv().TweenToPlayer then
							range3 = math.max((tonumber(getgenv().PvPOffsetY) or 9) + 6, range2)
						else
							range3 = range2
						end
						return range3
					end

					-- pA6443: HumanoidRootParts of everything the m1 loops may hit within `distance`, nearest first.
					-- NPCs: the Kill Aura set (any NPC without a force field), the Tween To NPC selection, and the named quest mobs / bosses the farms fight.
					getgenv().targetsInRange = function(distance)
						local parts = {}
						local character = LocalPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local npcs = workspace:FindFirstChild("NPCs")
						if npcs and root then
							for _, child in ipairs(npcs:GetChildren()) do
								local name = child.Name:lower()
								local selected = getgenv().TweenToNPC and getgenv().SelectedNPC and child.Name == getgenv().SelectedNPC
								if not (getgenv().KillAura and not getgenv().npcHasForceField(child) or selected or name:find("scient") or name:find("law")
									or child.Name == "Donmingo Family" or child.Name == "Fishman Karate User" or child.Name == "Yeti" or child.Name == "Crazy Wolf"
									or child.Name == "Juzo the Diamondback" or child.Name == "Roger" or child.Name == "Hawk Eye") then
									continue
								end
								local npcRoot = child:FindFirstChild("HumanoidRootPart")
								local humanoid = child:FindFirstChildOfClass("Humanoid")
								if npcRoot and humanoid and humanoid.Health > 0 then
									if (npcRoot.Position - root.Position).Magnitude <= distance then
										table.insert(parts, npcRoot)
									end
								end
							end
						end
						if getgenv().TweenToPlayer and root then
							local playerRange = math.min(distance, tonumber(getgenv().PvPRange) or 2000)
							for _, player in ipairs(Players:GetPlayers()) do
								if not getgenv().PvPSkippable(player) then
									local playerRoot = player.Character:FindFirstChild("HumanoidRootPart")
									if (playerRoot.Position - root.Position).Magnitude <= playerRange then
										table.insert(parts, playerRoot)
									end
								end
							end
						end
						if (getgenv().AutoFactory or getgenv().AutoFarmGearCyborg) and root then
							local env = workspace:FindFirstChild("Env")
							local factoryPool = env and env:FindFirstChild("FactoryPool")
							local hitbox = factoryPool and factoryPool:FindFirstChild("hitbox")
							local barrelHP = factoryPool and factoryPool:FindFirstChild("barrelHP")
							if hitbox and hitbox:IsA("BasePart") and (not barrelHP or barrelHP.Value and barrelHP.Value > 0) then
								if (hitbox.Position - root.Position).Magnitude <= 50 then
									table.insert(parts, hitbox)
								end
							end
						end
						if root and #parts > 1 then
							local origin = root.Position
							table.sort(parts, function(a, b)
								return (a.Position - origin).Magnitude < (b.Position - origin).Magnitude
							end)
						end
						return parts
					end

					-- pA4106 (identical to the BigMom module's getgenv().targetBlocking, which is used when it exists)
					local function localTargetBlocking(instance)
						if not (instance and instance.Parent) then
							return false
						end
						if getgenv().isNPCBlocking and getgenv().isNPCBlocking(instance) then
							return true, "a Blocking flag"
						end
						local ok, result = pcall(function()
							return instance:GetAttribute("IsBlocking")
						end)
						if ok and result == true then
							return true, "IsBlocking"
						end
						local humanoid = instance:FindFirstChildOfClass("Humanoid")
						local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
						if animator then
							local blockAnim = nil
							pcall(function()
								for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
									local animation = track.Animation
									local animationId = animation and string.match(tostring(animation.AnimationId), "%d+")
									if animationId and (getgenv().BlockAnimIds or {})[animationId] then
										blockAnim = getgenv().BlockAnimIds[animationId]
										return
									end
									if animation and string.find(string.lower(animation.Name or ""), "block", 1, true) then
										blockAnim = animation.Name
										return
									end
								end
							end)
							if blockAnim then
								return true, "the " .. tostring(blockAnim) .. " animation"
							end
						end
						return false
					end

					local function targetBlocking(instance)
						local fn = getgenv().targetBlocking or localTargetBlocking
						return fn(instance)
					end

					-- Fake-m1-on-block switch per farm mode. INFERRED: the UI toggles NPCFeintOnBlock / PvPFeintOnBlock (pA3242 / pA250) call an unrecovered "apply"
					-- routine; the lifts read the combined getgenv().FeintOnBlock. Here the mode flag decides, and an explicit FeintOnBlock = false still wins.
					local function feintEnabled()
						if getgenv().FeintOnBlock == false then
							return false
						end
						if getgenv().TweenToPlayer then
							return getgenv().PvPFeintOnBlock ~= false
						end
						return getgenv().NPCFeintOnBlock ~= false
					end

					-- pA7297: when the target is blocking, send a fake swing (no damage) and wait FeintRetry seconds; true = "do not hit now".
					local feintState = setmetatable({}, { __mode = "k" })

					getgenv().farmFeint = function(part, weaponType, index, animation)
						local model = part and part.Parent
						-- Lane F3's keyed version (pA7204: Juzo / Roger / Mihawk / NPC / PvP FeintOnBlock + FeintRetry) is the only reader of the per-boss "Fake M1 On Block"
						-- switches; it decides for every model that has a key, the combined-flag logic below handles everything else.
						local keyed, keyFor = getgenv().bossFeint, getgenv().bossKeyFor
						if keyed and keyFor and model and keyFor(model) then
							return keyed(part, weaponType, index, animation) == true
						end
						if not feintEnabled() then
							return false
						end
						if not model then
							return false
						end
						local blocking, why = targetBlocking(model)
						if not blocking then
							if feintState[model] and getgenv().FeintLog ~= false and getgenv().BMLog then
								getgenv().BMLog(string.format("[Feint] '%s' dropped the block after %.1fs - m1ing for real.", tostring(model.Name), tick() - feintState[model].since))
							end
							feintState[model] = nil
							return false
						end
						local last = feintState[model]
						if last and tick() - last.at < (getgenv().FeintRetry or 5) then
							return true
						end
						pcall(function()
							ReplicatedStorage.Events.CombatRegister:InvokeServer({ "swingsfx", weaponType, index, "Ground", false, animation, 2, 1.5 })
						end)
						feintState[model] = { at = tick(), since = last and last.since or tick() }
						getgenv().Feints = (getgenv().Feints or 0) + 1
						if getgenv().FeintLog ~= false and getgenv().BMLog then
							getgenv().BMLog(string.format("[Feint] '%s' is blocking (%s) - fake m1, no damage. Waiting for the unblock, feinting again in %ds if it holds (x%d).",
								tostring(model.Name), tostring(why), math.floor(getgenv().FeintRetry or 5), getgenv().Feints))
						end
						return true
					end

					-- INFERRED (pA2968 / pA538 `upvN(list)`): pick the first target; when fake-m1 is off, targets that are blocking are skipped, and if every
					-- target is blocking nothing is returned (the loops count that in AttacksAllBlocking).
					getgenv().pickAttackTarget = function(list)
						for _, part in ipairs(list) do
							if part and part.Parent then
								if feintEnabled() or not targetBlocking(part.Parent) then
									return part
								end
							end
						end
						return nil
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 05_VerticalTP (final/missing_farm/F2/05_VerticalTP.lua) =====
				do
					-- F2 / 05_VerticalTP: the vertical-teleport stage of TweenToCFrame (altitude changes bigger than VerticalTpStep, default 900 studs, are done in hops with the
					-- game's facingMouse stance switched on).
					--   stepVerticalTP pA967, ensureVertFaceMouse pA4214, vertFaceMouseOff pA1099 (+ its retry loop pA900; pA5441 is a one-line caller).
					-- Caller shape (pA1890, the TweenToCFrame vertical thread):
					--   stepVerticalTP(rootPart, goalY, "TweenToCFrame", function() return tweenState.Enabled and tweenState.Conn == myConnection end)
					--   -> true, hops   when the remaining gap is <= VerticalTpStep (the normal flight covers it), false, hops   when it gave up.
					-- Settings read (no hub defaults exist, the `or` values below are the lifts' own): VerticalTpStep 900, VerticalTpHold 2, VerticalTpFaceWait 1.5, VerticalTpOffWait 3.
					local Players = game:GetService("Players")
					local RunService = game:GetService("RunService")
					local LocalPlayer = Players.LocalPlayer

					local function vtpLog(message)
						if getgenv().BMLog then
							getgenv().BMLog(message)
						end
					end

					-- pA4214: make sure the character is in the facingMouse stance (attribute "facingMouse" == true); waits up to VerticalTpFaceWait for the server to confirm.
					getgenv().ensureVertFaceMouse = function(character)
						getgenv().VertOffToken = (getgenv().VertOffToken or 0) + 1 -- cancels a pending vertFaceMouseOff loop
						character = character or LocalPlayer.Character
						if not character then
							return false
						end
						if character:GetAttribute("facingMouse") == true then
							return true
						end
						getgenv().vertFaceMouse(true)
						local deadline = os.clock() + (getgenv().VerticalTpFaceWait or 1.5)
						repeat
							task.wait(0.05)
						until character:GetAttribute("facingMouse") == true or os.clock() > deadline
						return character:GetAttribute("facingMouse") == true
					end

					-- pA1099 (pA900 is the body of its spawned loop): switch the stance off again and keep sending "off" until the attribute drops (or VerticalTpOffWait runs out).
					getgenv().vertFaceMouseOff = function()
						getgenv().VertOffToken = (getgenv().VertOffToken or 0) + 1
						local token = getgenv().VertOffToken
						pcall(function()
							local env = getgenv().AimStanceEnv
							if env then
								env.FaceMouse = false
							end
						end)
						task.spawn(function()
							local deadline = os.clock() + (getgenv().VerticalTpOffWait or 3)
							local character
							repeat
								if getgenv().VertOffToken ~= token then
									return
								end
								getgenv().vertFaceMouse(false)
								task.wait(0.3)
								character = LocalPlayer.Character
							until not character or character:GetAttribute("facingMouse") ~= true or os.clock() > deadline
						end)
					end

					-- pA967
					getgenv().stepVerticalTP = function(part, targetY, label, stillActive)
						local step = getgenv().VerticalTpStep or 900
						local hops = 0
						while part and part.Parent and (not stillActive or stillActive()) do
							if not getgenv().ensureVertFaceMouse(part.Parent) then
								vtpLog(string.format("[VTP] %s: facingMouse would not turn on - not hopping.", tostring(label)))
								return false, hops
							end
							local gap = targetY - part.Position.Y
							if math.abs(gap) <= step then
								return true, hops
							end
							local hopY = part.Position.Y + math.sign(gap) * step
							part.CFrame = CFrame.new(part.Position.X, hopY, part.Position.Z) * part.CFrame.Rotation
							part.AssemblyLinearVelocity = Vector3.zero
							hops += 1
							getgenv().VerticalTpHops = (getgenv().VerticalTpHops or 0) + 1
							-- hold the part still for VerticalTpHold seconds and measure how far the server pulls it back
							local pulledBack = 0
							local connection = RunService.Heartbeat:Connect(function()
								if not part.Parent then
									return
								end
								part.AssemblyLinearVelocity = Vector3.zero
								local drift = math.abs(part.Position.Y - hopY)
								if drift > pulledBack then
									pulledBack = drift
								end
							end)
							local deadline = os.clock() + (getgenv().VerticalTpHold or 2)
							repeat
								task.wait(0.1)
							until os.clock() >= deadline or stillActive and not stillActive()
							connection:Disconnect()
							if stillActive and not stillActive() then
								return false, hops
							end
							if pulledBack > 50 then
								vtpLog(string.format("[VTP] %s: hop %d got pulled back %d studs - stopping.", tostring(label), hops, math.floor(pulledBack)))
								return false, hops
							end
							vtpLog(string.format("[VTP] %s: hop %d %+d to Y %d held, %d left (x%d)", tostring(label), hops, math.sign(gap) * step, math.floor(hopY),
								math.floor(math.abs(targetY - hopY)), getgenv().VerticalTpHops))
						end
						return false, hops
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 10_Tween (final/missing_farm/F2/10_Tween.lua) =====
				do
					-- F2 / 10_Tween: the movement engine the farms call (TweenToCFrame, TweenToMob, TweenToMob2) + isScriptMover / ScriptOwnsMovement / bossShuffleOffset.
					--
					-- EXACT (lifted by lane F6 once the lost VM keys were solved, see final/missing_farm/F6/README.txt):
					--   TweenToCFrame step  = pA7991 (hub fn23)   horizontal BodyVelocity at constant Speed (+ linear velocity clamp 2x Speed), vertical placement by a per-frame CFrame snap
					--                                             (ground snap / obstacle climb / TweenInstantY / clampYUp), frame-based arrival and snap-on-close, stuck detection, stun hold.
					--   TweenToMob2 step    = pA10783             constant-speed steering, Attached flag, snap-on-close (TeleportDistance 15), gyro on the goal, Hawk Eye offsets, BossKey
					--                                             offsets + bossShuffleOffset, once-a-second re-target.
					--   TweenToMob step     = pA995               head (9 look-ahead rays, Aggro re-target); its tail is the same code as pA10783's.
					--   Setup / cleanup     = pA1231 (CFrame), pA9338 (Mob), pA7947 (Mob2), pA5778 / pA6215 (stop).
					-- RECONSTRUCTED (marked RECONSTRUCTED below; nothing in any lift): the reaction to a look-ahead ray HIT (mob engines), the one-frame "stun just ended" path (CFrame engine
					--   falls through), the four helper closures bias / clearance / blocked / freeSpot of the CFrame step, findMob (nearest living model by name), the time-out teardown
					--   (the lift returns right after the log), and the logging hooks mayLog / recordPosition (omitted).
					-- Hub helpers called (all exist in hub_full.lua, all exported through getgenv()): holdAboveWater, SnapGroundY, climbLanding, clampYUp, landAfterTween, MarkTweenArrived,
					--   LogTweenClimb, RecordTweenRequest, releaseAimStance, firebreathMovementHeld, isStunned / isCharacterDowned, StopCurrentTween, __TensenTweenState, BMLog.  Each call is guarded:
					--   a missing helper degrades to "no snap / no climb" instead of an error.
					local Players = game:GetService("Players")
					local RunService = game:GetService("RunService")
					local LocalPlayer = Players.LocalPlayer

					-- pA5667 deletes exactly these names when it clears the script's movers; the hub's anti-stun remover and the anti-knockback loops (pA966 / pA3638) ask
					-- getgenv().isScriptMover(name) before destroying a BodyVelocity / BodyGyro.  INFERRED strong (the function itself is in no lift).
					local scriptMoverNames = {
						BM_ReactVel = true,
						BM_DodgeGyro = true,
						BM_MochiHold = true,
						KD_TweenGyro = true,
						KD_TweenVel = true,
						KD_CFrameGyro = true,
						KD_CFrameVel = true,
						KD_AttachGyro = true,
						KD_AttachVel = true,
					}

					if getgenv().isScriptMover == nil then
						getgenv().isScriptMover = function(name)
							if scriptMoverNames[name] then
								return true
							end
							if type(name) == "string" and (name:sub(1, 3) == "KD_" or name:sub(1, 3) == "BM_") then
								return true
							end
							return false
						end
					end

					local function tweenState()
						local state = getgenv().__TensenTweenState
						if not state then
							state = { Enabled = false, Gyro = nil, Vel = nil, Conn = nil, Gen = 0, AtGoal = false }
							getgenv().__TensenTweenState = state
						end
						return state
					end

					-- INFERRED (weak): used by pA2316 / pA10352 (movement smoothing) and optionally by the knockback loops.
					if getgenv().ScriptOwnsMovement == nil then
						getgenv().ScriptOwnsMovement = function(root, humanoid)
							if tweenState().Enabled then
								return true
							end
							if root then
								for _, child in ipairs(root:GetChildren()) do
									if (child:IsA("BodyVelocity") or child:IsA("BodyGyro")) and getgenv().isScriptMover(child.Name) then
										return true
									end
								end
							end
							return false
						end
					end

					local function bmLog(message)
						if getgenv().BMLog then
							getgenv().BMLog(message)
						end
					end

					-- ---- noclip (the hub's own is a hub-scope local; this one switches itself off as soon as the tween is over) --------------------------------------------
					local noclipParts = {}
					local noclipConn = nil

					local function setNoclip(on)
						if on then
							if noclipConn then
								return
							end
							noclipConn = RunService.Stepped:Connect(function()
								if not tweenState().Enabled then
									-- the tween ended without calling us (StopCurrentTween): release
									if noclipConn then
										noclipConn:Disconnect()
										noclipConn = nil
									end
									for part, original in pairs(noclipParts) do
										if part.Parent then
											part.CanCollide = original
										end
										noclipParts[part] = nil
									end
									return
								end
								local character = LocalPlayer.Character
								if not character then
									return
								end
								for _, part in ipairs(character:GetDescendants()) do
									if part:IsA("BasePart") and part.CanCollide then
										if noclipParts[part] == nil then
											noclipParts[part] = true
										end
										part.CanCollide = false
									end
								end
							end)
						else
							if noclipConn then
								noclipConn:Disconnect()
								noclipConn = nil
							end
							for part, original in pairs(noclipParts) do
								if part.Parent then
									part.CanCollide = original
								end
								noclipParts[part] = nil
							end
						end
					end

					-- ---- M1 back-and-forth for every BossKey --------------------------------------------------------------------------------------------------------------------
					-- pA10783 calls getgenv().bossShuffleOffset(BossKey, mobRoot) for Juzo / Roger / Mihawk / NPC / PvP.  The function itself is in no lift; the settings are
					-- <Key>Shuffle (toggle) / <Key>ShuffleStuds / <Key>ShufflePeriod (seconds) written by the boss, NPC and PvP tabs.  RECONSTRUCTED with the law of the BigMom module's
					-- m1ShuffleOffset (pA1829): every Period the phase flips; in "through him" mode (M1ShuffleThrough, default on) the hover point alternates between the normal point and
					-- Studs further out along the line from the target to us.
					local shuffleStates = {}

					if getgenv().bossShuffleOffset == nil then
						getgenv().bossShuffleOffset = function(key, mobRoot)
							local g = getgenv()
							if type(key) ~= "string" or g[key .. "Shuffle"] ~= true or not mobRoot then
								return Vector3.zero
							end
							local character = LocalPlayer.Character
							local root = character and character:FindFirstChild("HumanoidRootPart")
							if not root then
								return Vector3.zero
							end
							local studs = tonumber(g[key .. "ShuffleStuds"]) or 12
							local period = tonumber(g[key .. "ShufflePeriod"]) or 0.4
							local shuffle = shuffleStates[key]
							if not shuffle then
								shuffle = { at = 0, phase = 1, dir = nil }
								shuffleStates[key] = shuffle
							end
							local flat = Vector3.new(root.Position.X - mobRoot.Position.X, 0, root.Position.Z - mobRoot.Position.Z)
							local now = tick()
							if now - shuffle.at >= period then
								shuffle.at = now
								shuffle.phase = shuffle.phase == 1 and -1 or 1
								shuffle.dir = nil
							end
							if not (shuffle.dir and shuffle.dir.Magnitude > 0.001) then
								shuffle.dir = flat.Magnitude > 0.001 and flat.Unit or Vector3.new(0, 0, 1)
							end
							if g.M1ShuffleThrough ~= false then
								if shuffle.phase == 1 then
									return shuffle.dir * studs
								end
								return Vector3.zero
							end
							return shuffle.dir * (studs * shuffle.phase)
						end
					end

					-- ---- RECONSTRUCTED helpers of the CFrame step (the lift calls four closures of the parent whose bodies are not identified) -----------------------------------
					-- bias(pos) -> Vector3 added to the goal before the steering direction / facing are taken.  Unknown; zero = steer straight at the goal.
					local function bias(position)
						return Vector3.zero
					end

					local function blocked(position, ignore)
						-- is there something solid within 2 studs of this point (four horizontal probes + one up)?
						local params = RaycastParams.new()
						params.FilterType = Enum.RaycastFilterType.Exclude
						params.FilterDescendantsInstances = ignore or {}
						for _, direction in ipairs({ Vector3.new(2, 0, 0), Vector3.new(-2, 0, 0), Vector3.new(0, 0, 2), Vector3.new(0, 0, -2), Vector3.new(0, 3, 0) }) do
							local hit = workspace:Raycast(position, direction, params)
							if hit and hit.Instance and hit.Instance.CanCollide then
								return true
							end
						end
						return false
					end

					local function freeSpot(position, ignore, radius)
						-- nearest unblocked point on rings of radius/4, radius/2, radius around the spot (8 directions each); the spot itself when nothing is free
						for _, ring in ipairs({ radius / 4, radius / 2, radius }) do
							for i = 0, 7 do
								local angle = i * math.pi / 4
								local candidate = position + Vector3.new(math.cos(angle) * ring, 0, math.sin(angle) * ring)
								if not blocked(candidate, ignore) then
									return candidate
								end
							end
						end
						return position
					end

					local function clearance(position, maxStep, params)
						-- how far up (0..maxStep) the character has to go for a short forward ray to clear the obstacle in front of it
						local character = LocalPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local look = root and root.CFrame.LookVector or Vector3.new(0, 0, -1)
						local flatLook = Vector3.new(look.X, 0, look.Z)
						if flatLook.Magnitude < 0.01 then
							return 0
						end
						flatLook = flatLook.Unit
						local rise = 0
						local increment = math.max(0.5, maxStep / 8)
						while rise <= maxStep do
							local hit = workspace:Raycast(position + Vector3.new(0, rise, 0), flatLook * 6, params)
							if not (hit and hit.Instance) then
								return rise
							end
							rise += increment
						end
						return maxStep
					end

					-- ---- RECONSTRUCTED: nearest living model of that name in the container (pA13 `findMob(hrp, name, container, flag2)`: body not in any lift) ----------------------------------
					-- flag2 (pA995: "the current mob is aggro'd on someone and a free one exists") prefers mobs without a true Aggro value and skips `exclude`.
					local function findMob(root, mobName, container, flag2, exclude)
						local best, bestDistance = nil, math.huge
						for _, model in ipairs(container:GetChildren()) do
							if model.Name == mobName and model ~= exclude then
								local humanoid = model:FindFirstChildOfClass("Humanoid")
								local part = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
								if part and part.Parent and not (humanoid and humanoid.Health <= 0 and humanoid.MaxHealth > 0) then
									local aggro = model:FindFirstChild("Aggro")
									if not (flag2 and aggro and aggro.Value == true) then
										local distance = (part.Position - root.Position).Magnitude
										if distance < bestDistance then
											best, bestDistance = model, distance
										end
									end
								end
							end
						end
						return best
					end

					-- look / right / up of a CFrame.  RightVector and UpVector always exist in Roblox; the fallbacks only keep a minimal test stub from breaking the step.
					local function axes(cf)
						local look = cf.LookVector
						local right = cf.RightVector or Vector3.new(-look.Z, 0, look.X)
						local up = cf.UpVector or Vector3.new(0, 1, 0)
						return look, right, up
					end

					local function hawkEyeDodging()
						local stamp = getgenv().HawkEyeDodging
						return stamp and tick() - stamp < 2
					end

					local function isDowned(character)
						local fn = getgenv().isCharacterDowned or getgenv().isStunned
						if fn then
							local ok, result = pcall(fn, character)
							return ok and result == true
						end
						return false
					end

					-- ---- the engine -------------------------------------------------------------------------------------------------------------------------------------------------------
					-- spec = { kind = "cframe" | "mob", mobKind = 1 | 2 (TweenToMob / TweenToMob2), name, cfg, speed, noclip, walkOnWater, maxTime, ... }
					local function startEngine(spec)
						local g = getgenv()
						if g.EvadingBoss or g.LowHealthAnchored then
							return false
						end
						if g.LowHealthActive and not g.LowHealthSelfTween then
							return false
						end
						local state = tweenState()
						if state.Enabled == true then
							return false
						end
						if g.combatPaused and g.combatPaused() then
							return false
						end
						local character = LocalPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if not root or not humanoid or humanoid.Health <= 0 then
							return false
						end
						local isMob = spec.kind == "mob"
						local mob = nil
						if isMob then
							mob = findMob(root, spec.mobName, spec.container, false, nil)
							if not mob then
								return false
							end
						end

						if g.RecordTweenRequest then
							pcall(g.RecordTweenRequest, isMob and "mob" or "cframe", spec.cfg)
						end
						setNoclip(false)
						if g.releaseAimStance then
							pcall(g.releaseAimStance)
						end
						local stop = g.StopCurrentTween
						if stop then
							stop()
						end
						state.Enabled = true
						state.AtGoal = false
						state.Attached = false
						state.ClimbStartTime = nil
						state.ClimbTpUsed = nil
						state.IsMobTween = isMob or nil
						state.BossKey = spec.bossKey
						setNoclip(spec.noclip)
						g.NoclipOverride = isMob
						g.OverrideType = isMob and "Noclip" or ""
						g.WaterOverride = true
						g.WaterOverrideType = spec.walkOnWater and "Collide" or "NoCollide"
						humanoid.PlatformStand = true
						humanoid.AutoRotate = false
						if not (g.firebreathMovementHeld and g.firebreathMovementHeld()) then
							root.Anchored = false
						end

						local gyro = Instance.new("BodyGyro")
						gyro.Name = isMob and "KD_TweenGyro" or "KD_CFrameGyro"
						gyro.P = 200000
						gyro.D = isMob and (g.ChaseGyroD or 1000) or 1000
						gyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
						gyro.CFrame = root.CFrame
						gyro.Parent = root
						local velocity = Instance.new("BodyVelocity")
						velocity.Name = isMob and "KD_TweenVel" or "KD_CFrameVel"
						velocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
						velocity.Velocity = Vector3.zero
						velocity.Parent = root
						state.Gyro = gyro
						state.Vel = velocity

						local myGen = state.Gen
						local connection = nil
						local startCharacter = character
						local startClock = tick()
						local vtpPhase = nil -- nil | "run" | "done" (vertical-teleport stage, see 05_VerticalTP.lua)
						local usedVtp = false

						local raycastParams = RaycastParams.new()
						raycastParams.FilterType = Enum.RaycastFilterType.Exclude
						raycastParams.FilterDescendantsInstances = { character }

						local function cleanup(arrived)
							pcall(function()
								velocity.Velocity = Vector3.zero
							end)
							pcall(function()
								gyro:Destroy()
							end)
							pcall(function()
								velocity:Destroy()
							end)
							if state.Conn == connection and connection then
								state.Conn = nil
							end
							if connection then
								connection:Disconnect()
							end
							if state.Gen == myGen then
								state.Enabled = false
								state.Gyro = nil
								state.Vel = nil
								state.IsMobTween = nil
								state.Attached = false
								state.ClimbStartTime = nil
								state.AtGoal = arrived == true
								if arrived and getgenv().MarkTweenArrived then
									pcall(getgenv().MarkTweenArrived)
								end
							end
							setNoclip(false)
							if usedVtp and getgenv().vertFaceMouseOff then
								pcall(getgenv().vertFaceMouseOff)
							end
							pcall(function()
								root.AssemblyLinearVelocity = Vector3.zero
								root.AssemblyAngularVelocity = Vector3.zero
							end)
							pcall(function()
								humanoid.PlatformStand = false
								humanoid.AutoRotate = true
							end)
							getgenv().WaterOverride = false
							getgenv().NoclipOverride = false
						end

						-- ======================================================================================================================================================
						-- TweenToCFrame step  (pA7991 / hub fn23, EXACT unless marked)
						-- ======================================================================================================================================================
						local lastProgress = tick()
						local lastFlat = Vector3.new(root.Position.X, 0, root.Position.Z)
						local stuckUntil = 0
						local stunStart = nil
						local currentCharacter = character

						local function cframeStep(dt)
							local gg = getgenv()
							local cfg = spec.cfg
							local speed = spec.speed
							if gg.firebreathMovementHeld and gg.firebreathMovementHeld() then
								-- firebreath hold: stand still, the clock does not run
								velocity.Velocity = Vector3.zero
								startClock += dt
								lastProgress = tick()
								return
							end
							if vtpPhase == "run" then
								velocity.Velocity = Vector3.zero
								startClock += dt
								return
							end
							local timedOut = tick() - startClock >= spec.maxTime
							if not state.Enabled or gg.EvadingBoss or gg.LowHealthAnchored or timedOut then
								if timedOut and state.Enabled then
									-- RECONSTRUCTED: the lift sets TweenNeedsRetween, logs, and returns (junk values) without tearing down; a tween that never ends would hang every
									-- caller that waits for `Enabled == false`, so the teardown the other branch performs is done here too.
									gg.TweenNeedsRetween = true
									bmLog(string.format("[Tween] Timed out after %ds still %d studs from the goal - NOT an arrival.", math.floor(spec.maxTime),
										math.floor((spec.cframe.Position + spec.offset - root.Position).Magnitude)))
								end
								cleanup(false)
								return
							end
							if gg.holdAboveWater then
								gg.holdAboveWater(root)
							end

							local character2 = LocalPlayer.Character
							if not character2 or not character2.Parent then
								return -- skips the frame, does not end the tween
							end
							if not root or root.Parent ~= character2 then
								root = character2:FindFirstChild("HumanoidRootPart")
							end
							if not humanoid or humanoid.Parent ~= character2 then
								humanoid = character2:FindFirstChildOfClass("Humanoid")
							end
							if not root or not humanoid then
								return
							end
							if currentCharacter ~= character2 then
								currentCharacter = character2
								raycastParams.FilterDescendantsInstances = { currentCharacter }
							end
							if gyro.Parent ~= root then
								gyro.Parent = root -- the movers follow the root part
							end
							if velocity.Parent ~= root then
								velocity.Parent = root
							end

							-- ADDED (not in the lift): a dead humanoid ends the tween.  The lift gets there through isStunned (the hub counts Health <= 0 as downed) and holds for up to
							-- 6 s; the hub's CharacterAdded handler stops the tween at the respawn anyway, so callers waiting for `Enabled == false` would only be delayed.
							if humanoid.Health <= 0 then
								cleanup(false)
								return
							end

							-- stun hold (EXACT)
							local isStunned = gg.isStunned or gg.isCharacterDowned
							if isStunned and isStunned(character2) then
								velocity.Velocity = Vector3.zero
								pcall(function()
									root.AssemblyLinearVelocity = Vector3.zero
									root.AssemblyAngularVelocity = Vector3.zero
								end)
								if not stunStart then
									stunStart = tick()
									gg.subStatus = "Stunned - holding the tween"
								end
								local limit = cfg.StunHoldMax or gg.TweenStunHoldMax or 6
								if limit < tick() - stunStart then
									bmLog(string.format("[Tween] Held by a stun for %ds - dropping the tween so it can be re-fired.", math.floor(tick() - stunStart)))
									gg.TweenNeedsRetween = true
									cleanup(false)
									return
								end
								startClock += dt -- the stun does not count against MaxTime
								return
							end
							if stunStart then
								stunStart = nil
								humanoid.PlatformStand = true
								humanoid.AutoRotate = false
								if not (gg.firebreathMovementHeld and gg.firebreathMovementHeld()) then
									root.Anchored = false
								end
								-- RECONSTRUCTED: the lift is cut right here (one lost key); it falls through to the normal flow below.
							end

							-- stuck detection (EXACT): less than 4 flat studs of progress for 1.5 s -> 0.6 s of climb mode
							local now = tick()
							local flat = Vector3.new(root.Position.X, 0, root.Position.Z)
							if (flat - lastFlat).Magnitude > 4 then
								lastFlat = flat
								lastProgress = now
							elseif 1.5 < now - lastProgress then
								lastProgress = now
								stuckUntil = now + 0.6
							end

							-- goal and steering point
							local goal = spec.cframe.Position + spec.offset
							local steer = goal + bias(root.Position)
							local position = root.Position

							-- look-ahead: five rays from the root, the first hit decides how Y is adjusted (EXACT rays; the order is the lift's)
							local reach = math.max(5, speed * dt * 2.5)
							local look, right, up = axes(root.CFrame)
							local sideReach = math.max(3, reach - 2)
							local p = root.Position
							local hit = nil
							for _, ray in ipairs({
								{ p, look * reach },
								{ p + right * 1.5, look * sideReach },
								{ p - right * 1.5, look * sideReach },
								{ p + up * 1.5, look * sideReach },
								{ p - up * 1.5, look * sideReach },
							}) do
								hit = workspace:Raycast(ray[1], ray[2], raycastParams)
								if hit and hit.Instance then
									break
								end
								hit = nil
							end
							if hit and hit.Instance then
								local instance = hit.Instance
								local normal = hit.Normal
								local isBarrier = tostring(instance.CollisionGroup or ""):match("Barrier") ~= nil
									or string.find(string.lower(instance:GetFullName()), "barrier", 1, true) ~= nil
								local floorLike = math.abs(normal:Dot(Vector3.new(0, 1, 0))) >= 0.75
								local parent = instance.Parent
								local isCharacter = parent ~= nil
									and (parent:FindFirstChild("Humanoid") ~= nil or (parent.Parent ~= nil and parent.Parent:FindFirstChild("Humanoid") ~= nil))
								local landing = nil
								if not floorLike and not isCharacter and gg.climbLanding then
									local okLanding, result = pcall(gg.climbLanding, root, position, normal, instance, raycastParams, { currentCharacter }, "TweenToCFrame")
									if okLanding then
										landing = result
									end
								end
								if landing then
									if landing.Y - root.Position.Y > (gg.TweenClimbLogMin or 8) and gg.LogTweenClimb then
										pcall(gg.LogTweenClimb, "TweenToCFrame", instance.Name, isBarrier, root.Position.Y, landing.Y)
									end
									position = landing -- snap up / over the obstacle
								else
									position = Vector3.new(position.X, root.Position.Y + clearance(root.Position, 10, raycastParams), position.Z)
								end
							end

							-- vertical placement for this frame (EXACT order)
							if now < stuckUntil then
								position = Vector3.new(position.X, root.Position.Y + clearance(root.Position, math.max(1.5, speed * dt), raycastParams), position.Z)
							else
								local down = workspace:Raycast(position, Vector3.new(0, -2000, 0), raycastParams)
								if down and down.Instance then
									local spot = Vector3.new(position.X, down.Position.Y + 5, position.Z)
									if blocked(spot, { currentCharacter }) then
										spot = freeSpot(spot, { currentCharacter }, 20)
									end
									if gg.SnapGroundY then
										local okSnap, snapped = pcall(gg.SnapGroundY, "TweenToCFrame", root, spot, down.Instance)
										position = okSnap and snapped or spot
									else
										position = spot
									end
								end
							end
							if gg.TweenInstantY ~= false and now >= stuckUntil then
								if goal.Y - position.Y > (tonumber(gg.TweenInstantYGap) or 6) then
									position = Vector3.new(position.X, goal.Y, position.Z) -- far below the goal: jump straight to its height
								end
							end
							if gg.clampYUp then
								local okClamp, clamped = pcall(gg.clampYUp, root, position, "TweenToCFrame")
								if okClamp and typeof(clamped) == "Vector3" then
									position = clamped
								end
							end
							if not (gg.firebreathMovementHeld and gg.firebreathMovementHeld()) then
								root.CFrame = CFrame.new(position) * root.CFrame.Rotation -- the per-frame snap (rotation kept)
							end
							root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z)

							-- facing, arrival, horizontal velocity (EXACT)
							local toSteer = steer - root.Position
							local toGoal = goal - root.Position
							local flatToGoal = Vector3.new(toGoal.X, 0, toGoal.Z).Magnitude
							if flatToGoal == 0 then
								flatToGoal = 0.001
							end
							local step = speed * dt -- one frame of travel
							local snapRadius = math.max(1, step * 1.5)
							local arriveRadius = math.max(0.5, step * 1.2)
							local face = Vector3.new(steer.X, root.Position.Y, steer.Z)
							if (face - root.Position).Magnitude > 0.001 then
								gyro.CFrame = CFrame.new(root.Position, face)
							end
							if not (spec.teleportOnClose and flatToGoal <= snapRadius) then
								if flatToGoal <= arriveRadius then -- arrived without a snap
									gg.WaterOverride = false
									velocity.Velocity = Vector3.zero
									root.AssemblyLinearVelocity = Vector3.zero
									root.AssemblyAngularVelocity = Vector3.zero
									local landedAt = root.Position
									cleanup(true) -- MarkTweenArrived, tear down, Enabled = false
									if gg.landAfterTween then
										pcall(gg.landAfterTween, landedAt, "TweenToCFrame")
									end
								else
									local dir = Vector3.new(toSteer.X, 0, toSteer.Z)
									if dir.Magnitude == 0 then
										dir = Vector3.new(1, 0, 0)
									end
									velocity.Velocity = dir.Unit * speed -- constant horizontal speed, no ramp
									local v = root.AssemblyLinearVelocity
									if v.Magnitude > speed * 2 then
										root.AssemblyLinearVelocity = v.Unit * (speed * 2)
									end
								end
								return
							end
							-- TeleportOnClose and within 1.5 frames of travel: snap onto the goal and finish
							gg.ForceDisableFastWalk = true
							gg.WaterOverride = false
							if not (gg.firebreathMovementHeld and gg.firebreathMovementHeld()) then
								root.CFrame = CFrame.new(goal) * root.CFrame.Rotation
							end
							root.AssemblyLinearVelocity = Vector3.zero
							root.AssemblyAngularVelocity = Vector3.zero
							velocity.Velocity = Vector3.zero
							cleanup(true)
							if gg.landAfterTween then
								pcall(gg.landAfterTween, goal, "TweenToCFrame")
							end
							task.delay(0.05, function()
								getgenv().ForceDisableFastWalk = false
							end)
						end

						-- ======================================================================================================================================================
						-- TweenToMob2 / TweenToMob step  (pA10783 / pA995, EXACT unless marked)
						-- ======================================================================================================================================================
						local lastRetarget = 0

						local function mobStep(dt)
							local gg = getgenv()
							local cfg = spec.cfg
							local speed = spec.speed
							if vtpPhase == "run" then
								return
							end
							if spec.maxTime and tick() - startClock >= spec.maxTime then
								cleanup(false) -- MaxTime: plain cleanup, no TweenNeedsRetween here
								return
							end
							local character2 = LocalPlayer.Character
							local humanoid2 = character2 and character2:FindFirstChild("Humanoid")
							if not character2 or not humanoid2 or humanoid2.Health <= 0 or character2 ~= startCharacter then
								cleanup(false) -- the character changed or died: end the tween
								return
							end
							if not state.Attached and isDowned(character2) then
								cleanup(false)
								return
							end
							if gg.IsStunnedOverride then -- stunned: stand still, keep the tween
								velocity.Velocity = Vector3.zero
								return
							end

							-- re-target at most once a second when the mob is gone / dead (TweenToMob also when the mob is aggro'd on someone and a free one exists)
							local now = tick()
							local mobHumanoid = mob and mob:FindFirstChildOfClass("Humanoid")
							local needRetarget, flag2 = false, false
							if not mob or not mob.Parent or not mobHumanoid or mobHumanoid.Health <= 0 then
								needRetarget = true
							elseif spec.mobKind == 1 then
								local aggro = mob:FindFirstChild("Aggro")
								if aggro and aggro.Value == true then
									local other = findMob(root, spec.mobName, spec.container, true, mob)
									if other then
										needRetarget, flag2 = true, true
									end
								end
							end
							if needRetarget and 1 <= now - lastRetarget then
								-- RECONSTRUCTED: the lift calls stopTween(false) here and then assigns the new mob; a literal teardown would destroy the movers the next lines
								-- drive, so the tween is kept when a new mob is found and ended (below) when none is left.
								lastRetarget = now
								mob = findMob(root, spec.mobName, spec.container, flag2, flag2 and mob or nil) or (flag2 and mob or nil)
							end
							if not mob or not mob.Parent then
								cleanup(false)
								return
							end
							local mobRoot = mob:FindFirstChild("HumanoidRootPart") or mob.PrimaryPart
							if not mobRoot then
								return
							end

							-- behind distance and hover offset
							local behind = spec.behind
							local offsetVector = spec.offset
							if mob.Name == "Hawk Eye" or spec.mobName == "Hawk Eye" then
								if hawkEyeDodging() then
									behind = 18 -- 18 behind, 15 up while Hawk Eye dodges
									offsetVector = Vector3.new(0, 15, 0)
								else
									behind = 8 -- 8 behind, 14 up
									offsetVector = Vector3.new(0, 14, 0)
								end
							end
							local shuffle = Vector3.zero
							if spec.mobKind == 2 and cfg.BossKey then
								local dodging = cfg.BossKey == "Mihawk" and hawkEyeDodging()
								local y = tonumber(gg[cfg.BossKey .. "OffsetY"]) -- "<Key>OffsetY" slider replaces the hover height
								if y and not dodging then
									offsetVector = Vector3.new(offsetVector.X, y, offsetVector.Z)
								end
								if not dodging and gg.bossShuffleOffset then
									shuffle = gg.bossShuffleOffset(cfg.BossKey, mobRoot)
								end
							end
							local goal = mobRoot.Position + -mobRoot.CFrame.LookVector * behind + offsetVector + shuffle
							local toGoal = goal - root.Position
							if gg.holdAboveWater then
								gg.holdAboveWater(root, goal.Y)
							end
							local teleportDistance = cfg.TeleportDistance or 15
							local away = root.Position - goal
							local climbBoost = 0

							-- Raycast option: while farther than TeleportDistance, look ahead (5 rays for TweenToMob2, 9 for TweenToMob; EXACT origins / directions / reach)
							if spec.raycastEnabled and not (away.Magnitude <= teleportDistance) then
								local p = root.Position
								local look, right, up = axes(root.CFrame)
								local reach = math.max(5, speed * dt * 2.5)
								local sideReach = math.max(3, reach - 2)
								raycastParams.FilterDescendantsInstances = { LocalPlayer.Character or startCharacter }
								local rays = {
									{ p, look * reach },
									{ p + right * 1.5, look * sideReach },
									{ p - right * 1.5, look * sideReach },
									{ p + up * 1.5, look * sideReach },
									{ p - up * 1.5, look * sideReach },
								}
								if spec.mobKind == 1 then
									rays[#rays + 1] = { p + right * 1.2, (look + right * 0.75).Unit * reach }
									rays[#rays + 1] = { p - right * 1.2, (look - right * 0.75).Unit * reach }
									rays[#rays + 1] = { p + look * 0.5, right * 2.8 }
									rays[#rays + 1] = { p + look * 0.5, -right * 2.8 }
								end
								local hit = nil
								for _, ray in ipairs(rays) do
									hit = workspace:Raycast(ray[1], ray[2], raycastParams)
									if hit and hit.Instance then
										break
									end
									hit = nil
								end
								if hit and hit.Instance then
									local instance = hit.Instance
									local isBarrier = tostring(instance.CollisionGroup or ""):match("Barrier") ~= nil
									local parent = instance.Parent
									local isCharacter = parent ~= nil and (parent:FindFirstChild("Humanoid") ~= nil or (parent.Parent ~= nil and parent.Parent:FindFirstChild("Humanoid") ~= nil))
									if gg.LogTweenClimb and (isBarrier or not isCharacter) then
										pcall(gg.LogTweenClimb, spec.name, instance.Name, isBarrier, root.Position.Y, root.Position.Y + reach)
									end
									-- RECONSTRUCTED (the lifts lose everything after the hit): a solid obstacle that is not a character is climbed by adding upward speed this frame
									if not isCharacter and instance.CanCollide ~= false then
										climbBoost = speed
										state.ClimbStartTime = state.ClimbStartTime or now
									end
								else
									state.ClimbStartTime = nil
								end
							end

							-- ---- steering (EXACT) ----
							local flatDistance = Vector3.new(toGoal.X, 0, toGoal.Z).Magnitude
							local distance = toGoal.Magnitude
							if distance == 0 then
								distance = 0.001
							end
							local aim = Vector3.new(goal.X, root.Position.Y, goal.Z) -- face the goal horizontally
							if (aim - root.Position).Magnitude > 0.001 then
								gyro.CFrame = CFrame.new(root.Position, aim)
							end

							if cfg.TeleportOnClose ~= false and distance <= teleportDistance then
								-- close: snap onto the hover point (rotation kept), stop, mark attached.  (The chase-position logging hooks mayLog / recordPosition are omitted.)
								root.CFrame = CFrame.new(goal) * root.CFrame.Rotation
								root.AssemblyLinearVelocity = Vector3.zero
								root.AssemblyAngularVelocity = Vector3.zero
								velocity.Velocity = Vector3.zero
								state.Attached = true
								return
							end

							if distance <= spec.stopDistance or (spec.raycastEnabled and flatDistance <= 4) then
								velocity.Velocity = Vector3.zero
								root.AssemblyLinearVelocity = Vector3.zero
								state.Attached = true
							else
								state.Attached = false
								if gg.releaseAimStance then
									gg.releaseAimStance()
								end
								if not spec.raycastEnabled then
									velocity.Velocity = toGoal.Unit * speed -- full 3-D direction, constant speed, no ramp
									return
								end
								local flat = Vector3.new(toGoal.X, 0, toGoal.Z) -- Raycast on: horizontal only (the height is held by PlatformStand / holdAboveWater)
								if flat.Magnitude > 0.001 then
									velocity.Velocity = flat.Unit * speed + Vector3.new(0, climbBoost, 0)
								else
									velocity.Velocity = Vector3.new(0, climbBoost, 0)
								end
							end
						end

						local step = isMob and mobStep or cframeStep
						connection = RunService.Heartbeat:Connect(function(dt)
							-- stopped from outside (StopCurrentTween bumps Gen and already destroyed the movers) or replaced
							if state.Gen ~= myGen or state.Conn ~= connection then
								cleanup(false)
								return
							end
							local ok, err = pcall(step, dt)
							if not ok then
								bmLog("[Tween] step failed: " .. tostring(err))
								cleanup(false)
							end
						end)
						state.Conn = connection

						-- TweenToCFrame, pA1890: altitude changes beyond VerticalTpStep (900) are hopped first (facingMouse stance + vertical teleports), the flight starts after.
						-- Smaller gaps never needed it in the lift (stepVerticalTP returns at once), so the stance is not touched for them.
						if not isMob and getgenv().stepVerticalTP then
							local goalPosition = spec.cframe.Position + spec.offset
							if math.abs(goalPosition.Y - root.Position.Y) > (getgenv().VerticalTpStep or 900) then
								vtpPhase = "run"
								usedVtp = true
								task.spawn(function()
									local ok, done = pcall(getgenv().stepVerticalTP, root, goalPosition.Y, "TweenToCFrame", function()
										return state.Enabled and state.Conn == connection
									end)
									if ok and done and state.Enabled and state.Conn == connection then
										vtpPhase = "done"
									else
										vtpPhase = nil
										if state.Conn == connection then
											cleanup(false)
										end
									end
								end)
							end
						end
						return true
					end

					-- ---- entry points ---------------------------------------------------------------------------------------------------------------------------------------------------------
					-- TweenToCFrame (pA1231).  cfg: CFrame, Speed (60), Offset, TeleportOnClose (true), WalkOnWater (true), Noclip (true), MaxTime (20), StunHoldMax.
					-- StopDistance / TeleportDistance are accepted and ignored: the real step does not use them (arrival = 1.2 frames of travel, snap = 1.5 frames).
					local function tweenToCFrame(cfg)
						cfg = cfg or {}
						local cframe = cfg.CFrame
						if typeof(cframe) == "Vector3" then
							cframe = CFrame.new(cframe)
						end
						if not cframe then
							return false
						end
						return startEngine({
							kind = "cframe",
							cfg = cfg,
							name = "TweenToCFrame",
							cframe = cframe,
							offset = cfg.Offset or Vector3.zero,
							speed = cfg.Speed or 60,
							noclip = cfg.Noclip ~= false,
							walkOnWater = cfg.WalkOnWater ~= false,
							teleportOnClose = cfg.TeleportOnClose ~= false,
							maxTime = cfg.MaxTime or 20,
						})
					end

					-- TweenToMob (pA9338 / pA995) and TweenToMob2 (pA7947 / pA10783, adds BehindDistance and the BossKey handling).
					-- cfg: MobName ("Fishman Karate User"), Speed (70), Offset, Container (workspace), StopDistance (3), Raycast (true), WalkOnWater (true), BehindDistance (0),
					-- TeleportOnClose (true), TeleportDistance (15), MaxTime (none), BossKey.
					local function mobTween(cfg, mobKind)
						cfg = cfg or {}
						return startEngine({
							kind = "mob",
							mobKind = mobKind,
							cfg = cfg,
							name = mobKind == 1 and "TweenToMob" or "TweenToMob2",
							bossKey = cfg.BossKey,
							mobName = cfg.MobName or "Fishman Karate User",
							container = cfg.Container or workspace,
							offset = cfg.Offset or Vector3.zero,
							behind = mobKind == 2 and (cfg.BehindDistance or 0) or 0,
							speed = cfg.Speed or 70,
							noclip = true,
							walkOnWater = cfg.WalkOnWater ~= false,
							stopDistance = cfg.StopDistance or 3,
							raycastEnabled = cfg.Raycast ~= false,
							maxTime = cfg.MaxTime,
						})
					end

					local function tweenToMob(cfg)
						return mobTween(cfg, 1)
					end

					local function tweenToMob2(cfg)
						return mobTween(cfg, 2)
					end

					-- Always reachable as getgenv().__F2Tween.*; the public names are only taken when no earlier snippet already defined them.
					getgenv().__F2Tween = { TweenToCFrame = tweenToCFrame, TweenToMob = tweenToMob, TweenToMob2 = tweenToMob2 }

					if rawget(getgenv(), "TweenToCFrame") == nil then
						getgenv().TweenToCFrame = tweenToCFrame
					end

					if rawget(getgenv(), "TweenToMob") == nil then
						getgenv().TweenToMob = tweenToMob
					end

					if rawget(getgenv(), "TweenToMob2") == nil then
						getgenv().TweenToMob2 = tweenToMob2
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 20_M1Loops (final/missing_farm/F2/20_M1Loops.lua) =====
				do
					-- F2 / 20_M1Loops: the two attack loops every farm shares.  Kill Aura is not a loop of its own: turning it on widens combatRange()
					-- and makes targetsInRange() return every NPC around (00_Core.lua).
					--   Melee loop = pA2968, Sword loop = pA538 (PikaV2 swings count as sword swings: weaponNow maps it to "Sword").
					-- Each loop is inert (one yield per frame) while no farm flag is set or the weapon class does not match.
					local Players = game:GetService("Players")
					local ReplicatedStorage = game:GetService("ReplicatedStorage")
					local LocalPlayer = Players.LocalPlayer

					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end

					-- Fake-m1-on-block dispatcher.  Targets that belong to a settings key (Juzo / Roger / Mihawk, the selected NPC, a player in Tween To Player) use the keyed
					-- version bossFeint (pA7204, F3: honours <Key>FeintOnBlock / <Key>FeintRetry of the boss tabs); every other target uses the generic farmFeint (00_Core.lua).
					-- true = do not hit now.
					local function feint(g, part, weaponType, index, animation)
						local model = part and part.Parent
						if model and g.bossKeyFor and g.bossFeint and g.bossKeyFor(model) then
							return g.bossFeint(part, weaponType, index, animation)
						end
						return g.farmFeint(part, weaponType, index, animation)
					end

					local function anyFarm(g)
						return g.autofarm or g.haki or g.KillAura or g.TweenToNPC or g.TweenToPlayer
					end

					local function anyBoss(g)
						return g.AutoJuzoBoss or g.AutoRogerBoss or g.AutoMihawkBoss or g.AutoFactory or g.AutoFarmGearCyborg
					end

					local function anyFlag(g)
						return g.autofarm or g.haki or g.AutoJuzoBoss or g.AutoMihawkBoss or g.AutoRogerBoss or g.AutoFactory or g.AutoFarmGearCyborg or g.KillAura
							or g.TweenToNPC or g.TweenToPlayer
					end

					-- combo tables (identical to the BigMom module's tbl5 / tbl7: index sent to the server + animation name)
					local meleeCombo = {
						{ anim = "Punch1", index = 1 },
						{ anim = "Punch2", index = 2 },
						{ anim = "Punch3", index = 3 },
						{ anim = "GroundPunch4", index = 4 },
					}

					local swordCombo = {
						{ anim = "Slash1", index = 1 },
						{ anim = "Slash2", index = 2 },
						{ anim = "Slash3", index = 3 },
						{ anim = "GroundSlash4", index = 4 },
					}

					local function combatRemote()
						local events = ReplicatedStorage:FindFirstChild("Events")
						return events and events:FindFirstChild("CombatRegister")
					end

					local function hitDelay(g)
						local fn = anyBoss(g) and g.bossHitDelay or g.farmHitDelay
						if type(fn) == "function" then
							local ok, value = pcall(fn)
							if ok and type(value) == "number" then
								return value
							end
						end
						return tonumber(g.HitWait) or 0.4
					end

					local function startLoop(key, step)
						local token = {}
						loops[key] = token
						task.spawn(function()
							task.wait()
							while task.wait() do
								if loops[key] ~= token then
									break
								end
								local ok, err = pcall(step)
								if not ok and getgenv().BMLog and os.clock() - (getgenv().__F2LastLoopErr or 0) > 10 then
									getgenv().__F2LastLoopErr = os.clock()
									getgenv().BMLog("[F2] " .. key .. " step failed: " .. tostring(err))
								end
							end
						end)
					end

					-- ---- Melee (pA2968) -------------------------------------------------------------------------------------------------
					do
						local combo = 1
						local lastSwing = 0

						startLoop("F2.M1Melee", function()
							local g = getgenv()
							if not anyFlag(g) then
								combo = 1
								return
							end
							local meleeFarm = g.weaponNow(g.WeaponType) == "Melee" and anyFarm(g)
							local meleeBoss = g.weaponNow(g.WeaponTypeBoss) == "Melee" and anyBoss(g)
							if not (meleeFarm or meleeBoss) then
								return
							end
							local character = g.Char()
							if g.combatPaused() then
								return
							end
							if not g.equippedMelee(character) then
								return
							end
							if tick() - lastSwing < hitDelay(g) then
								return
							end
							local root = character:FindFirstChild("HumanoidRootPart")
							if not root then
								return
							end
							local targets = g.targetsInRange(g.combatRange())
							if #targets == 0 then
								combo = 1
								return
							end
							local target = g.pickAttackTarget(targets)
							if not target then
								g.AttacksAllBlocking = (g.AttacksAllBlocking or 0) + 1
								return
							end
							if not (target.Position and root.Position) then
								return
							end
							local step = meleeCombo[combo]
							if not step then
								combo = 1
								return
							end
							g.dropAimStance()
							local animation = ReplicatedStorage.CombatAnimations.Melee[step.anim]
							if feint(g, target, "Melee", step.index, animation) then
								lastSwing = tick()
								return
							end
							local remote = combatRemote()
							if not remote then
								return
							end
							remote:InvokeServer({ "swingsfx", "Melee", step.index, "Ground", false, animation, 2, 1.5 })
							local offset = target.Position - root.Position
							if offset.Magnitude == 0 then
								offset = root.CFrame.LookVector
							end
							remote:InvokeServer({
								"damage",
								targets,
								"Melee",
								{ step.index, "Ground", "Melee" },
								true,
								CFrame.new(target.Position - offset.Unit * 5 + Vector3.new(0, 1, 0), target.Position),
								aircombo = "Ground",
							})
							lastSwing = tick()
							combo += 1
							if combo > 4 then
								combo = 1
							end
						end)
					end

					-- ---- Sword (pA538) --------------------------------------------------------------------------------------------------
					do
						local combo = 1
						local lastSwing = 0

						startLoop("F2.M1Sword", function()
							local g = getgenv()
							if not anyFlag(g) then
								combo = 1
								return
							end
							local swordFarm = g.weaponNow(g.WeaponType) == "Sword" and anyFarm(g)
							local swordBoss = g.weaponNow(g.WeaponTypeBoss) == "Sword" and anyBoss(g)
							if not (swordFarm or swordBoss) then
								return
							end
							local character = g.Char()
							if g.combatPaused() then
								return
							end
							local swords = ReplicatedStorage.Modules.SwordHandle.Swords
							local swordName = nil
							for _, child in pairs(swords:GetChildren()) do
								if character:FindFirstChild(child.Name) and g.swordNameAllowed(child.Name) then
									swordName = child.Name
									break
								end
							end
							if not swordName then
								return
							end
							if tick() - lastSwing < hitDelay(g) then
								return
							end
							local root = character:FindFirstChild("HumanoidRootPart")
							if not root then
								return
							end
							local targets = g.targetsInRange(g.combatRange())
							if #targets == 0 then
								combo = 1
								return
							end
							local target = g.pickAttackTarget(targets)
							if not target then
								g.AttacksAllBlocking = (g.AttacksAllBlocking or 0) + 1
								return
							end
							if not (target.Position and root.Position) then
								return
							end
							local step = swordCombo[combo]
							if not step then
								combo = 1
								return
							end
							g.dropAimStance()
							local slash = swords[swordName].Slashes[step.anim]
							if feint(g, target, "Sword", step.index, slash) then
								lastSwing = tick()
								return
							end
							local remote = combatRemote()
							if not remote then
								return
							end
							remote:InvokeServer({ "swingsfx", "Sword", step.index, "Ground", false, slash, 2, 1.5 })
							if not target.Position or not root.Position then
								return
							end
							local offset = target.Position - root.Position
							if offset.Magnitude == 0 then
								offset = root.CFrame.LookVector
							end
							remote:InvokeServer({
								"damage",
								targets,
								"Sword",
								{ step.index, "Ground", "Sword" },
								true,
								CFrame.new(target.Position - offset.Unit * 5 + Vector3.new(0, 1, 0), target.Position),
								aircombo = "Ground",
							})
							lastSwing = tick()
							combo += 1
							if combo > 4 then
								combo = 1
							end
						end)
					end

					-- ---- Kill Aura weapon keeper (pA212) --------------------------------------------------------------------------------------------------------------------
					-- Once a second: with Kill Aura on (and not fishing, storing a fruit or touring an NPC) and something in range, make sure the farm weapon is in hand.
					-- The lift's `pcall(upvN)` is INFERRED to be the farm weapon equip routine (pA2247): nothing else would put a weapon in hand for Kill Aura.
					do
						local token = {}
						loops["F2.KillAuraEquip"] = token
						task.spawn(function()
							task.wait()
							while task.wait(1) do
								if loops["F2.KillAuraEquip"] ~= token then
									break
								end
								pcall(function()
									local g = getgenv()
									if g.KillAura and not g.TweenToNPC and not g.AutoFishing and not g.StoringFruit and #g.targetsInRange(g.combatRange()) > 0 then
										pcall(g.equipFarmWeapon)
									end
								end)
							end
						end)
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 30_TweenToNPCPlayer (final/missing_farm/F2/30_TweenToNPCPlayer.lua) =====
				do
					-- F2 / 30_TweenToNPCPlayer: the "Tween To NPC" loop (pA4221) and the "Tween To Player" loop (pA4160).
					-- Both only chase; the swings come from the m1 loops (20_M1Loops.lua), which widen their reach for these two modes (combatRange / targetsInRange).
					-- Both stand down while any other farm is running.  Upvalue bindings: tween state = getgenv().__TensenTweenState, stop = getgenv().StopCurrentTween,
					-- equip = getgenv().equipFarmWeapon (INFERRED name; the lifts call it as pcall(upvN)), findNearestAlive = pA8246, PvPTarget = pA1975.
					-- The two empty `if flag then end` shells of the lifts are where the lifter lost the statement; they are restored as "stop the tween we started"
					-- (INFERRED: without it switching the toggle off would leave the character flying at the last target).
					local Players = game:GetService("Players")
					local LocalPlayer = Players.LocalPlayer

					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end

					local function tweenState()
						return getgenv().__TensenTweenState or { Enabled = false }
					end

					local function stopTween()
						local stop = getgenv().StopCurrentTween
						if stop then
							stop()
						end
					end

					local function startLoop(key, interval, step)
						local token = {}
						loops[key] = token
						task.spawn(function()
							task.wait()
							while task.wait(interval) do
								if loops[key] ~= token then
									break
								end
								local ok, err = pcall(step)
								if not ok and getgenv().BMLog and os.clock() - (getgenv().__F2LastLoopErr or 0) > 10 then
									getgenv().__F2LastLoopErr = os.clock()
									getgenv().BMLog("[F2] " .. key .. " step failed: " .. tostring(err))
								end
							end
						end)
					end

					-- ---- Tween To NPC (pA4221) -----------------------------------------------------------------------------------------------------------------------------
					do
						local running = false

						startLoop("F2.TweenToNPC", 0.5, function()
							local g = getgenv()
							local otherFarm = g.autofarm or g.haki or g.AutoJuzoBoss or g.AutoMihawkBoss or g.AutoRogerBoss or g.AutoFishing or g.AutoMerchant or g.StartTweenIsland
							if not (g.TweenToNPC and g.SelectedNPC and g.SelectedNPC ~= "None") or otherFarm then
								if running and tweenState().Enabled and tweenState().IsMobTween then
									stopTween()
								end
								running = false
								return
							end
							local character = LocalPlayer.Character
							local humanoid = character and character:FindFirstChildOfClass("Humanoid")
							running = true
							if not humanoid or humanoid.Health <= 0 then
								return
							end
							if g.NPCAutoEquip ~= false then
								pcall(g.equipFarmWeapon)
							end
							if not tweenState().Enabled and g.findNearestAlive(g.SelectedNPC) then
								g.TweenToMob2({
									MobName = g.SelectedNPC,
									BossKey = "NPC",
									Speed = g.TweenSpeedMaster or 70,
									Offset = Vector3.new(0, tonumber(g.NPCOffsetY) or 9, 0),
									Container = workspace:FindFirstChild("NPCs") or workspace,
								})
							end
						end)
					end

					-- ---- Tween To Player (pA4160) --------------------------------------------------------------------------------------------------------------------------
					do
						local running = false
						local targetName = nil

						startLoop("F2.TweenToPlayer", 0.4, function()
							local g = getgenv()
							local otherFarm = g.autofarm or g.haki or g.AutoJuzoBoss or g.AutoMihawkBoss or g.AutoRogerBoss or g.AutoFishing or g.AutoMerchant or g.StartTweenIsland
								or g.TweenToNPC
							if not g.TweenToPlayer or otherFarm then
								if running and tweenState().Enabled and tweenState().IsMobTween then
									stopTween()
								end
								running = false
								targetName = nil
								return
							end
							local character = LocalPlayer.Character
							local humanoid = character and character:FindFirstChildOfClass("Humanoid")
							if not humanoid or humanoid.Health <= 0 then
								if tweenState().Enabled then
									stopTween()
								end
								running = true
								targetName = nil
								return
							end
							local player = g.PvPTarget()
							if not player or (targetName and targetName ~= player.Name) then
								if tweenState().Enabled then
									stopTween()
								end
								running = true
								targetName = nil
								if not player then
									return
								end
							end
							if g.PvPAutoEquip ~= false then
								pcall(g.equipFarmWeapon)
							end
							running = true
							if not tweenState().Enabled then
								targetName = player.Name
								g.TweenToMob2({
									MobName = player.Name,
									BossKey = "PvP",
									Speed = g.TweenSpeedMaster or 70,
									Offset = Vector3.new(0, tonumber(g.PvPOffsetY) or 9, 0),
									Container = player.Character and player.Character.Parent or workspace,
								})
							end
						end)
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 40_BusoKeeper (final/missing_farm/F2/40_BusoKeeper.lua) =====
				do
					-- F2 / 40_BusoKeeper: "Keep Buso Haki on" (UI toggle sets getgenv().Buso) and the automatic Buso while a farm runs (BusoFarmAutoOn, default on).
					--   busoCharge pA135, busoIsUp pA5333, pressBuso pA475, busoFarmActive pA7023, busoWanted pA1018, keeper loop pA2204.
					-- The BigMom module has its own Buso keeper (hub ~4347) that only runs in the Big Mom fight; this one covers every other farm.
					local Players = game:GetService("Players")
					local ReplicatedStorage = game:GetService("ReplicatedStorage")
					local LocalPlayer = Players.LocalPlayer

					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end

					local function busoLog(message)
						if getgenv().BMLog then
							getgenv().BMLog(message)
						end
					end

					-- pA135: Buso bar fill, 0..1, nil when the bar is not readable
					getgenv().busoCharge = function()
						local stats = ReplicatedStorage:FindFirstChild("Stats" .. LocalPlayer.Name)
						local bar = stats and stats:FindFirstChild(getgenv().BusoBarName or "BusoBar")
						if not bar then
							return nil
						end
						local ok, value, maxValue = pcall(function()
							return bar.Value, bar.MaxValue
						end)
						if not ok or type(value) ~= "number" or type(maxValue) ~= "number" or maxValue <= 0 then
							return nil
						end
						return math.clamp(value / maxValue, 0, 1)
					end

					-- pA5333: true while the Buso aura object is on the character, nil when there is no character
					getgenv().busoIsUp = function(character)
						local char = character or LocalPlayer.Character
						if not char or not char.Parent then
							return nil
						end
						return char:FindFirstChild(LocalPlayer.Name .. "Buso") ~= nil
					end

					-- pA475: press the Haki button (Events.Haki:FireServer("Buso")), at most once per BusoPressGap seconds
					getgenv().pressBuso = function(state)
						if os.clock() - (getgenv().LastBusoPress or 0) < (getgenv().BusoPressGap or 1) then
							return false
						end
						getgenv().LastBusoPress = os.clock()
						getgenv().BusoPresses = (getgenv().BusoPresses or 0) + 1
						pcall(function()
							ReplicatedStorage:WaitForChild("Events"):WaitForChild("Haki"):FireServer("Buso")
						end)
						if getgenv().BusoLog ~= false then
							busoLog(string.format("[Buso] pressed the haki button to turn it %s (x%d)", tostring(state), getgenv().BusoPresses))
						end
						return true
					end

					-- pA7023: any farm that fights is running (BusoFarmAutoOn = false opts out)
					getgenv().busoFarmActive = function()
						local g = getgenv()
						if g.BusoFarmAutoOn == false then
							return false
						end
						return g.autofarm == true or g.KillAura == true or g.TweenToNPC == true or g.TweenToPlayer == true or g.AutoJuzoBoss == true
							or g.AutoMihawkBoss == true or g.AutoRogerBoss == true or g.AutoFactory == true or g.AutoFarmGearCyborg == true
					end

					-- pA1018
					getgenv().busoWanted = function()
						return getgenv().Buso == true or getgenv().busoFarmActive()
					end

					-- pA2204: every 0.3 s, if Buso is wanted and the aura is down, press the button (unless the bar is below BusoRechargeFrac: it ran out, wait for it)
					do
						local token = {}
						loops["F2.Buso"] = token
						task.spawn(function()
							task.wait()
							while task.wait(0.3) do
								if loops["F2.Buso"] ~= token then
									break
								end
								pcall(function()
									local g = getgenv()
									if not g.busoWanted() then
										return
									end
									local character = LocalPlayer.Character
									if not (character and character.Parent) then
										return
									end
									local humanoid = character:FindFirstChildOfClass("Humanoid")
									if not (humanoid and humanoid.Health > 0) then
										return
									end
									local up = g.busoIsUp(character)
									if up == nil or up then
										return
									end
									local charge = g.busoCharge()
									local recharge = g.BusoRechargeFrac or 0.5
									if charge ~= nil and charge < recharge then
										g.BusoWaitedForBar = (g.BusoWaitedForBar or 0) + 1
										if g.BusoLog ~= false and os.clock() - (g.LastBusoWaitLog or 0) >= 3 then
											g.LastBusoWaitLog = os.clock()
											busoLog(string.format("[Buso] ran out - waiting for the bar to reach %d%% before re-enabling (now %d%%).", math.floor(recharge * 100), math.floor(charge * 100)))
										end
									else
										g.pressBuso("ON")
									end
								end)
							end
						end)
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 00_BossState (final/missing_farm/F3/00_BossState.lua) =====
				do
					-- F3 / 00_BossState: shared state and small helpers of the boss farms (Auto Juzo / Auto Roger / Auto Mihawk).
					-- Sources: pA3927 (Mihawk schedule), pA8969 (Roger schedule), pA6715 (umiBossComingUp), pA3689 (npcAlive), pA587 (bossAutoEquip),
					--          pA6097 (TweenToJuzoEntrance), pA2756 (TweenToUmiForRogerandMihawk).  Notes: 00_BossState.notes.md
					-- Every helper is a getgenv() entry that the loops (and other lanes) look up at call time.
					local g = getgenv()

					-- "killed this spawn window" flags shared by the farm loop, both schedule functions, umiBossComingUp and BossStatusText
					-- (pA844 upv9 / upv11, pA3927 upv1, pA8969 upv2, pA6715 upv3 / upv4, pA1119 upv5 / upv7).  engagedAt = pA844 upv6.
					local state = g.__TensenBossState
					if type(state) ~= "table" then
						state = {mihawkDone = false, rogerDone = false, engagedAt = nil}
						g.__TensenBossState = state
					end

					-- The CFrame the Umi trips aim at.  The lifted farm loop falls back to exactly this position when the setting is nil.
					-- INFERRED: the default itself (the lifts only ever read getgenv().UmiInstantCF; nothing in them assigns it).
					if g.UmiInstantCF == nil and CFrame then
						g.UmiInstantCF = CFrame.new(12512.18359375, 6.5736985206604, 2761.882080078125)
					end

					-- pA3927: Mihawk's window.  UTC+3 hour; odd hours open for the first 900 s of the hour; every call outside the window clears the done flag.
					-- returns untilOpen, secondsIntoHour, windowOpen
					g.MihawkSchedule = function()
						local t = os.date("!*t")
						local hour = (t.hour + 3) % 24
						local intoHour = t.min * 60 + t.sec
						if hour % 2 == 1 then
							if intoHour <= 900 then
								return 0, intoHour, true
							end
							state.mihawkDone = false
							return 7200 - intoHour, intoHour, false
						end
						state.mihawkDone = false
						return 3600 - intoHour, intoHour, false
					end

					-- pA8969: Roger's window: 5400 s cycle on the UTC+3 clock, open for the first 900 s.
					g.RogerSchedule = function()
						local t = os.date("!*t")
						local intoCycle = ((t.hour + 3) % 24 * 3600 + t.min * 60 + t.sec) % 5400
						if intoCycle <= 900 then
							return 0, intoCycle, true
						end
						state.rogerDone = false
						return 5400 - intoCycle, intoCycle, false
					end

					-- pA6715: Second Sea only.  True while a wanted Umi boss (toggle on, not done this cycle) is inside its window or opens within 180 s.
					g.umiBossComingUp = function()
						if game.PlaceId ~= 7465136166 then
							return false
						end
						local mihawkUntil, _, mihawkOpen = g.MihawkSchedule()
						local rogerUntil, _, rogerOpen = g.RogerSchedule()
						local mihawkWanted = g.AutoMihawkBoss and not state.mihawkDone
						local rogerWanted = g.AutoRogerBoss and not state.rogerDone
						return mihawkWanted and (mihawkUntil <= 180 or mihawkOpen) or rogerWanted and (rogerUntil <= 180 or rogerOpen)
					end

					-- pA3689: is there a living NPC called `name`?  Exact name, or (case-insensitive) substring of the NPC name; needs a Humanoid with Health > 0 and a root part.
					g.npcAlive = function(name)
						local npcs = workspace:FindFirstChild("NPCs")
						if not npcs then
							return false
						end
						local lowered = name and name:lower() or ""
						for _, child in pairs(npcs:GetChildren()) do
							if child.Name == name or lowered ~= "" and string.find(child.Name:lower(), lowered, 1, true) then
								local humanoid = child:FindFirstChildOfClass("Humanoid")
								local root = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart
								if humanoid and humanoid.Health > 0 and root then
									return true
								end
							end
						end
						return false
					end

					-- pA587: <key>AutoEquip (Juzo / Roger / Mihawk) switches the boss weapon in.  One equip at a time (debounced by `busy`).
					-- INFERRED: the lift calls an upvalue here (upv2 under pcall); WeaponTypeBoss is the boss weapon setting, equipBossWeapon (pA4929) is F2's function for it.
					local equipBusy = false
					g.bossAutoEquip = function(key)
						if getgenv()[key .. "AutoEquip"] == false then
							return
						end
						if equipBusy then
							return
						end
						equipBusy = true
						task.spawn(function()
							pcall(function()
								local equip = getgenv().equipBossWeapon
								if equip then
									equip()
								end
							end)
							equipBusy = false
						end)
					end

					-- pA6097: tween to Juzo's island door (the CFrame is the literal from the lift)
					g.TweenToJuzoEntrance = function()
						getgenv().TweenToCFrame({
							CFrame = CFrame.new(1770.34546, 36.0756149, -10659.0898, 0.98101902, 3.78205867e-09, -0.193911418, -4.64293626e-09, 1, -3.98506605e-09, 0.193911418, 4.80974416e-09, 0.98101902),
							Speed = getgenv().TweenSpeedAutoBoss or 110,
							StopDistance = 5,
							Raycast = true,
							TeleportOnClose = true,
							TeleportDistance = 5,
							CupidStyle = false,
							MaxTime = getgenv().BossTweenMaxTime or 10,
							HoverHeight = getgenv().BossTravelHoverHeight or 5,
						})
					end

					-- pA2756: tween to the Umi spot (getgenv().UmiInstantCF)
					g.TweenToUmiForRogerandMihawk = function()
						getgenv().TweenToCFrame({
							CFrame = getgenv().UmiInstantCF,
							Speed = getgenv().TweenSpeedAutoBoss or 110,
							StopDistance = 5,
							Raycast = true,
							TeleportOnClose = true,
							TeleportDistance = 5,
							CupidStyle = false,
							MaxTime = getgenv().BossTweenMaxTime or 10,
							HoverHeight = getgenv().BossTravelHoverHeight or 5,
						})
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 10_BossKeys (final/missing_farm/F3/10_BossKeys.lua) =====
				do
					-- F3 / 10_BossKeys: the per-boss settings plumbing ("Juzo" / "Roger" / "Mihawk" key prefix) that the boss tabs of the hub write.
					--   getgenv().bossKeyFor(model)          pA3423  model -> "Juzo" | "Roger" | "Mihawk" | "NPC" | "PvP" | nil   (by NPC name; NPC/PvP only while that tween mode is on)
					--   getgenv().bossTargetBlocking(model)  pA3190  the target is blocking: Blocking/Block child, Blocking/IsBlocking attribute, or a playing animation named *block*
					--   getgenv().bossFeint(part, weaponType, index, animation)   pA7204  keyed fake m1: while the target model has a key (bossKeyFor) whose
					--                                         <Key>FeintOnBlock is not false and it is blocking, send a "swingsfx" swing without damage, then wait <Key>FeintRetry s
					--                                         (default 5) before feinting again; true = do not hit now.  Keys: Juzo / Roger / Mihawk (boss tabs) and NPC / PvP
					--                                         (NPCFeintOnBlock / PvPFeintOnBlock and their Retry sliders in the Farm tab).
					-- The m1 loops of the farms (pA2968 / pA538 `upv10(part, weaponType, index, animation)`) skip the hit when this returns true.  pA7297 (the combined
					-- FeintOnBlock version) is the BigMom module's own copy and is already in the hub; the per-key settings of the Juzo / Mihawk / Roger tabs are only read here.
					-- Notes: 10_BossKeys.notes.md
					local g = getgenv()

					g.bossKeyFor = g.bossKeyFor or function(model)
						local name = model and model.Name
						if name == "Juzo the Diamondback" then
							return "Juzo"
						end
						if name == "Roger" then
							return "Roger"
						end
						if name == "Hawk Eye" or name == "Mihawk" then
							return "Mihawk"
						end
						if getgenv().TweenToNPC and name ~= nil and name == getgenv().SelectedNPC then
							return "NPC"
						end
						if getgenv().TweenToPlayer and name ~= nil and game:GetService("Players"):FindFirstChild(name) then
							return "PvP"
						end
						return nil
					end

					g.bossTargetBlocking = g.bossTargetBlocking or function(instance)
						if not (instance and instance.Parent) then
							return false
						end
						if instance:FindFirstChild("Blocking") or instance:FindFirstChild("Block") then
							return true
						end
						local ok, result = pcall(function()
							return instance:GetAttribute("Blocking") or instance:GetAttribute("IsBlocking")
						end)
						if ok and result == true then
							return true
						end
						local humanoid = instance:FindFirstChildOfClass("Humanoid")
						local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
						local blocking = false
						if animator then
							pcall(function()
								for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
									local animation = track.Animation
									if animation and string.find(string.lower(animation.Name or ""), "block", 1, true) then
										blocking = true
										return
									end
								end
							end)
						end
						return blocking
					end

					local lastFeint = setmetatable({}, {__mode = "k"})

					g.bossFeint = g.bossFeint or function(part, weaponType, index, animation)
						local model = part and part.Parent
						local key = model and getgenv().bossKeyFor(model)
						if not key or getgenv()[key .. "FeintOnBlock"] == false then
							return false
						end
						if not getgenv().bossTargetBlocking(model) then
							lastFeint[model] = nil
							return false
						end
						local last = lastFeint[model]
						if last and tick() - last < (tonumber(getgenv()[key .. "FeintRetry"]) or 5) then
							return true
						end
						pcall(function()
							game:GetService("ReplicatedStorage").Events.CombatRegister:InvokeServer({"swingsfx", weaponType, index, "Ground", false, animation, 2, 1.5})
						end)
						lastFeint[model] = tick()
						return true
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 20_BossMain (final/missing_farm/F3/20_BossMain.lua) =====
				do
					-- F3 / 20_BossMain: the boss farm loop for Auto Juzo / Auto Roger / Auto Mihawk (pA844).
					-- The lift of pA844 was a 371-state flattened machine; it was re-structured mechanically (tools/sm_unflatten.py), checked against the machine with a
					-- randomised stub world (tools/sm_diff.py, identical call/read/write trace), then named by hand.  Notes: 20_BossMain.notes.md
					--
					-- One iteration per 0.5 s:  nothing wanted -> idle; Fishing/Merchant on -> idle; dead -> wait; Roger/Mihawk toggle and their Umi window up (or already engaged)
					-- -> travel to Umi, then fight whichever boss is alive and not done this window; otherwise Juzo -> travel to his island, fight him, loot dwell, death wait.
					-- The fights themselves are done by TweenToMob2 (positioning) and the m1 loops; this loop only decides where we are and when a fight starts/ends.
					local JUZO_ISLAND = Vector3.new(1770.34546, 36.0756149, -10659.0898)
					local UMI_FALLBACK = Vector3.new(12512.18359375, 6.5736985206604, 2761.882080078125)

					local KEY = "F3.BossMain"
					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end
					local token = {}
					loops[KEY] = token

					local phase = nil -- "Turtle" (to Juzo) | "Turtle_Fight" | "Umi" | "Umi_Fight" | nil

					local function stale()
						return loops[KEY] ~= token
					end

					local function log(msg)
						local f = getgenv().BMLog
						if f then
							pcall(f, msg)
						end
					end

					local function tweenState()
						return getgenv().__TensenTweenState
					end

					local function stopTween()
						return getgenv().StopCurrentTween()
					end

					-- leave whatever phase we were in (stop the tween if one is running)
					local function resetPhase()
						if phase ~= nil then
							phase = nil
							if tweenState().Enabled then
								stopTween()
							end
						end
					end

					-- switch to a travel/fight phase: stop a running tween the first time
					local function enterPhase(name)
						if phase ~= name then
							if tweenState().Enabled then
								stopTween()
							end
							phase = name
						end
					end

					-- the one-time loot wait after a boss died (BossLootDwell, default 8 s); BossLootDwelling tells the other loops to stay put
					local function lootDwell()
						getgenv().BossLootDwelling = true
						local dwell = getgenv().BossLootDwell or 8
						task.wait(dwell)
						getgenv().BossLootDwelling = false
					end

					local function step()
						local g = getgenv()
						local state = g.__TensenBossState

						if not (g.AutoJuzoBoss or g.AutoRogerBoss or g.AutoMihawkBoss) then
							resetPhase()
							task.wait(0.5)
							return
						end
						if g.AutoFishing or g.AutoMerchant then
							resetPhase()
							task.wait(1)
							return
						end

						local player = game:GetService("Players").LocalPlayer
						local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
						local humanoid = player.Character and player.Character:FindFirstChild("Humanoid")
						if not root or not humanoid or humanoid.Health <= 0 then
							task.wait(1)
							return
						end

						local npcs = workspace:FindFirstChild("NPCs")
						if not npcs then
							return
						end

						-- Roger / Mihawk (Umi) take priority while their window is up or we are already committed to one
						local umiMode = (g.AutoRogerBoss or g.AutoMihawkBoss) and (g.umiBossComingUp() or g.UmiBossEngaged)
						local umiPos = g.UmiInstantCF and g.UmiInstantCF.Position or UMI_FALLBACK

						if umiMode then
							local umiDist = (root.Position - umiPos).Magnitude
							if umiDist > 150 then
								-- not at Umi yet: travel
								state.engagedAt = nil
								enterPhase("Umi")
								if not tweenState().Enabled then
									g.TweenToUmiForRogerandMihawk()
								end
								return
							end

							-- at Umi
							if not state.engagedAt then
								state.engagedAt = tick()
							end
							local _, _, mihawkWindowOpen = g.MihawkSchedule()
							local _, _, rogerWindowOpen = g.RogerSchedule()
							local mihawkTarget = g.AutoMihawkBoss and not state.mihawkDone and g.npcAlive("Hawk Eye")
							local rogerTarget = g.AutoRogerBoss and not state.rogerDone and g.npcAlive("Roger")

							-- a window that is open but whose boss never showed up within 120 s of arriving counts as done
							local mihawkExpired = g.AutoMihawkBoss and mihawkWindowOpen
							if mihawkExpired then
								mihawkExpired = not mihawkTarget
							end
							if mihawkExpired then
								mihawkExpired = state.engagedAt
							end
							if mihawkExpired then
								mihawkExpired = tick() - state.engagedAt >= 120
							end
							if mihawkExpired then
								state.mihawkDone = true
								state.engagedAt = nil
							end
							local rogerExpired = g.AutoRogerBoss and rogerWindowOpen
							if rogerExpired then
								rogerExpired = not rogerTarget
							end
							if rogerExpired then
								rogerExpired = state.engagedAt
							end
							if rogerExpired then
								rogerExpired = tick() - state.engagedAt >= 120
							end
							if rogerExpired then
								state.rogerDone = true
								state.engagedAt = nil
							end

							if mihawkTarget then
								-- ---- Mihawk ("Hawk Eye")
								getgenv().UmiBossEngaged = true
								if phase ~= "Umi_Fight" and tweenState().Enabled then
									stopTween()
								end
								getgenv().bossAutoEquip("Mihawk")
								local tweenToMob = getgenv().TweenToMob2
								local cfg = {MobName = "Hawk Eye", BossKey = "Mihawk", Raycast = false}
								cfg.Speed = getgenv().TweenSpeedAutoBoss or 70
								cfg.Offset = Vector3.new(0, 10, 0)
								cfg.Container = npcs
								tweenToMob(cfg)
								local fightOver
								repeat
									task.wait(0.15)
									getgenv().bossAutoEquip("Mihawk")
									local hawkEye = npcs:FindFirstChild("Hawk Eye")
									if hawkEye then
										hawkEye = getgenv().isHawkEyeCasting(hawkEye)
									end
									if hawkEye then
										getgenv().mihawkDodge()
									end
									fightOver = not tweenState().Enabled or not getgenv().AutoMihawkBoss or not getgenv().npcAlive("Hawk Eye")
								until fightOver or stale()
								if stale() then
									return
								end
								local bossDown = not getgenv().npcAlive("Hawk Eye")
								stopTween()
								state.mihawkDone = true
								state.engagedAt = nil
								getgenv().UmiBossEngaged = false
								if not getgenv().AutoMihawkBoss then
									phase = nil
								else
									if bossDown then
										lootDwell()
									end
									phase = "Umi_Fight"
								end
							elseif rogerTarget then
								-- ---- Roger
								local gv = getgenv()
								gv.UmiBossEngaged = true
								if phase ~= "Umi_Fight" and tweenState().Enabled then
									stopTween()
								end
								getgenv().bossAutoEquip("Roger")
								local tweenToMob = getgenv().TweenToMob2
								local cfg = {MobName = "Roger", BossKey = "Roger", Raycast = false}
								cfg.Speed = getgenv().TweenSpeedAutoBoss or 70
								cfg.Offset = Vector3.new(0, getgenv().BossHoverOffsetY or 10, 0)
								cfg.BehindDistance = getgenv().BossBehindDist or 0
								cfg.Container = npcs
								tweenToMob(cfg)
								local fightOver
								repeat
									task.wait(0.5)
									getgenv().bossAutoEquip("Roger")
									fightOver = not tweenState().Enabled
									if not fightOver then
										fightOver = not getgenv().AutoRogerBoss
									end
									if not fightOver then
										fightOver = not getgenv().npcAlive("Roger")
									end
								until fightOver or stale()
								if stale() then
									return
								end
								local bossDown = not getgenv().npcAlive("Roger")
								stopTween()
								state.rogerDone = true
								state.engagedAt = nil
								getgenv().UmiBossEngaged = false
								if not getgenv().AutoRogerBoss then
									phase = nil
								else
									if bossDown then
										lootDwell()
									end
									phase = "Umi_Fight"
								end
							else
								-- nobody to fight right now
								if not g.umiBossComingUp() then
									-- window over (or never wanted): release the Umi lock
									state.engagedAt = nil
									getgenv().UmiBossEngaged = false
									resetPhase()
								else
									enterPhase("Umi")
									if not tweenState().Enabled and umiDist > 15 then
										g.TweenToUmiForRogerandMihawk()
									end
								end
							end
							return
						end

						-- ---- Juzo
						if not getgenv().AutoJuzoBoss then
							resetPhase()
							return
						end
						state.engagedAt = nil
						local juzoDist = (root.Position - JUZO_ISLAND).Magnitude
						if juzoDist > 150 then
							enterPhase("Turtle")
							if not tweenState().Enabled then
								getgenv().TweenToJuzoEntrance()
							end
							return
						end
						if not g.npcAlive("Juzo the Diamondback") then
							-- at the island, waiting for him to spawn
							enterPhase("Turtle")
							if not tweenState().Enabled and juzoDist > 15 then
								getgenv().TweenToJuzoEntrance()
							end
							return
						end

						-- he is up: fight
						if phase ~= "Turtle_Fight" and tweenState().Enabled then
							stopTween()
						end
						getgenv().bossAutoEquip("Juzo")
						getgenv().JuzoFighting = true
						local diedMidFight = false
						while true do
							local fighting = getgenv().AutoJuzoBoss
							if fighting then
								fighting = getgenv().npcAlive("Juzo the Diamondback")
							end
							if fighting then
								local myHumanoid = player.Character and player.Character:FindFirstChild("Humanoid")
								local dead = not myHumanoid or myHumanoid.Health <= 0
								if not dead then
									if not tweenState().Enabled then
										local tweenToMob = getgenv().TweenToMob2
										local cfg = {MobName = "Juzo the Diamondback", BossKey = "Juzo", Raycast = true}
										cfg.Speed = getgenv().TweenSpeedAutoBoss or 70
										cfg.Offset = Vector3.new(0, getgenv().BossHoverOffsetY or 9.5, 0)
										cfg.BehindDistance = getgenv().BossBehindDist or 0
										cfg.TeleportDistance = getgenv().BossTeleportDistance or 20
										cfg.MaxTime = getgenv().BossFightTweenMaxTime
										cfg.Container = npcs
										tweenToMob(cfg)
									end
									getgenv().bossAutoEquip("Juzo")
									task.wait(0.5)
									if stale() then
										getgenv().JuzoFighting = false
										return
									end
									continue
								end
								diedMidFight = true
							end
							break
						end

						getgenv().JuzoFighting = false
						local bossDown = not getgenv().npcAlive("Juzo the Diamondback")
						stopTween()
						if not getgenv().AutoJuzoBoss then
							phase = nil
							return
						end
						if diedMidFight then
							-- we died: wait for the respawn (no loot dwell), then regroup
							local gv = getgenv()
							gv.BossDeaths = (getgenv().BossDeaths or 0) + 1
							log(string.format("[Juzo] we died mid fight (%d this session) - waiting for the respawn, no loot dwell", getgenv().BossDeaths))
							local diedAt = tick()
							local respawned
							repeat
								task.wait(0.5)
								local myHumanoid = player.Character and player.Character:FindFirstChild("Humanoid")
								local myRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
								respawned = myHumanoid and myRoot
								if not myHumanoid then
									respawned = myHumanoid
								end
								if respawned then
									respawned = myHumanoid.Health > 0
								end
								if not respawned then
									respawned = not getgenv().AutoJuzoBoss
								end
								if not respawned then
									local waited = tick() - diedAt
									respawned = waited > (getgenv().BossRespawnWait or 30)
								end
							until respawned or stale()
							if stale() then
								return
							end
							if not getgenv().AutoJuzoBoss then
								phase = nil
							else
								task.wait(getgenv().BossRegroupWait or 2)
								getgenv().bossAutoEquip("Juzo")
								phase = nil
							end
						else
							if bossDown then
								lootDwell()
							end
							phase = "Turtle_Fight"
						end
					end

					task.spawn(function()
						task.wait()
						while task.wait(0.5) do
							if stale() then
								break
							end
							local ok, err = pcall(step)
							if not ok then
								getgenv().JuzoFighting = false
								if os.clock() - (getgenv().__F3LastBossErr or 0) > 10 then
									getgenv().__F3LastBossErr = os.clock()
									log("[F3] boss loop step failed: " .. tostring(err))
								end
							end
						end
					end)
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 21_BossReTween (final/missing_farm/F3/21_BossReTween.lua) =====
				do
					-- F3 / 21_BossReTween: keep the Juzo chase tween alive (pA3733).  Inert unless getgenv().BossReTween is set (no default is assigned anywhere in the lifts).
					-- Once a second while JuzoFighting: if Juzo is alive and we are alive and the hub tween is idle (or BossReTweenAlways == true), count it and start the
					-- chase tween again with the same settings the main loop uses.  Notes: 21_BossReTween.notes.md
					local KEY = "F3.BossReTween"
					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end
					local token = {}
					loops[KEY] = token

					task.spawn(function()
						task.wait()
						while task.wait(1) do
							if loops[KEY] ~= token then
								break
							end
							pcall(function()
								local g = getgenv()
								if not g.JuzoFighting then
									return
								end
								if not g.BossReTween then
									return
								end
								local npcs = workspace:FindFirstChild("NPCs")
								if not npcs then
									return
								end
								local character = game:GetService("Players").LocalPlayer.Character
								local humanoid = character and character:FindFirstChild("Humanoid")
								if not (humanoid and not (humanoid.Health <= 0)) then
									return
								end
								if g.npcAlive("Juzo the Diamondback") then
									if not (g.BossReTweenAlways ~= true and g.__TensenTweenState.Enabled) then
										g.BossReTweens = (g.BossReTweens or 0) + 1
										g.StopCurrentTween()
										g.TweenToMob2({
											MobName = "Juzo the Diamondback",
											BossKey = "Juzo",
											Raycast = true,
											Speed = g.TweenSpeedAutoBoss or 70,
											Offset = Vector3.new(0, g.BossHoverOffsetY or 9.5, 0),
											BehindDistance = g.BossBehindDist or 0,
											TeleportDistance = g.BossTeleportDistance or 20,
											MaxTime = g.BossFightTweenMaxTime,
											Container = npcs,
										})
									end
								end
							end)
						end
					end)
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 22_JuzoFightHelpers (final/missing_farm/F3/22_JuzoFightHelpers.lua) =====
				do
					-- F3 / 22_JuzoFightHelpers: two small threads that only act while the Juzo fight flag (getgenv().JuzoFighting) is set.
					--   F3.JuzoBackstep  (pA4139)  taps S every frame: key down, 0.1 s, key up.
					--   F3.BossAutoBlock (pA9457)  getgenv().BossAutoBlock (default false): hold the block key while Juzo plays an attack animation (pA2763), at most 5 s.
					-- Notes: 22_JuzoFightHelpers.notes.md
					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end

					-- pA4176 / pA7254: key press through the VirtualInputManager
					local function sendKey(down, keyCode)
						pcall(function()
							game:GetService("VirtualInputManager"):SendKeyEvent(down, keyCode, false, game)
						end)
					end

					-- pA2763: Juzo is alive and an Action-priority animation (longer than 0.4 s, weight above 0.1) is playing on him
					local function juzoAttacking()
						local npcs = workspace:FindFirstChild("NPCs")
						local juzo = npcs and npcs:FindFirstChild("Juzo the Diamondback")
						if not juzo then
							return false
						end
						local humanoid = juzo:FindFirstChildOfClass("Humanoid")
						if not humanoid or humanoid.Health <= 0 then
							return false
						end
						local animator = humanoid:FindFirstChildOfClass("Animator")
						if not animator then
							return false
						end
						for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
							if track.Priority == Enum.AnimationPriority.Action or track.Priority == Enum.AnimationPriority.Action2 or track.Priority == Enum.AnimationPriority.Action3 or track.Priority == Enum.AnimationPriority.Action4 then
								if track.Length > 0.4 and track.WeightCurrent > 0.1 then
									return true
								end
							end
						end
						return false
					end
					getgenv().juzoAttacking = juzoAttacking

					do
						local KEY = "F3.JuzoBackstep"
						local token = {}
						loops[KEY] = token
						task.spawn(function()
							task.wait()
							while task.wait() do
								if loops[KEY] ~= token then
									break
								end
								if getgenv().JuzoFighting then
									sendKey(true, Enum.KeyCode.S)
									task.wait(0.1)
									sendKey(false, Enum.KeyCode.S)
								end
							end
						end)
					end

					do
						local KEY = "F3.BossAutoBlock"
						local token = {}
						loops[KEY] = token
						-- INFERRED (weak): the lift calls two upvalue closures to press and release the block; they have the shape of pA7254 (SendKeyEvent with a bound key).
						-- The block key in GPO is F, so that is the default; the BossBlockKey setting (an Enum.KeyCode) overrides it.
						local function blockKey()
							return getgenv().BossBlockKey or Enum.KeyCode.F
						end
						task.spawn(function()
							task.wait()
							while task.wait(0.1) do
								if loops[KEY] ~= token then
									break
								end
								if not getgenv().JuzoFighting then
									continue
								end
								if not getgenv().BossAutoBlock then
									continue
								end
								if not juzoAttacking() then
									continue
								end
								sendKey(true, blockKey())
								local pressedAt = tick()
								repeat
									task.wait()
								until not (juzoAttacking() and not (tick() - pressedAt > 5)) or loops[KEY] ~= token
								sendKey(false, blockKey())
							end
						end)
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 23_MihawkDodge (final/missing_farm/F3/23_MihawkDodge.lua) =====
				do
					-- F3 / 23_MihawkDodge: Hawk Eye (Mihawk) attack dodge.
					--   getgenv().isHawkEyeCasting(model)  pA9748   Hawk Eye is mid-move: a child named yoru/slash/stance/slice/barrage, or an Action-priority animation (> 0.4 s, weight > 0.1)
					--   getgenv().mihawkDodge()            pA10165  dash to 15 studs above / 18 behind Hawk Eye (at most every 0.6 s, only within 120 studs, only with Auto Mihawk on)
					--   getgenv().mihawkWatchChild(child)  pA5623   a new child of the Hawk Eye model whose name contains yoru/giant/slice/slash/thousand triggers the dodge
					--   F3.MihawkWatch                     INFERRED: the lifts do not contain the call site that wires pA5623 to an event.  This thread attaches it (pA1041 shape: run the
					--                                      handler on the existing children, then on ChildAdded) to the Hawk Eye model while Auto Mihawk is on.
					--                                      getgenv().MihawkChildDodge = false turns it off.
					-- Notes: 23_MihawkDodge.notes.md
					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end

					getgenv().isHawkEyeCasting = function(instance)
						if not instance then
							return false
						end
						for _, child in ipairs(instance:GetChildren()) do
							local name = child.Name:lower()
							if name:find("yoru") or name:find("slash") or name:find("stance") or name:find("slice") or name:find("barrage") then
								return true
							end
						end
						local humanoid = instance:FindFirstChildOfClass("Humanoid")
						local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
						if animator then
							for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
								if track.Priority == Enum.AnimationPriority.Action or track.Priority == Enum.AnimationPriority.Action2 or track.Priority == Enum.AnimationPriority.Action3 or track.Priority == Enum.AnimationPriority.Action4 then
									if track.Length > 0.4 and track.WeightCurrent > 0.1 then
										return true
									end
								end
							end
						end
						return false
					end

					local lastDodge = 0
					getgenv().mihawkDodge = function()
						if not getgenv().AutoMihawkBoss then
							return
						end
						if tick() - lastDodge < 0.6 then
							return
						end
						local player = game:GetService("Players").LocalPlayer
						local character = player.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local humanoid = character and character:FindFirstChild("Humanoid")
						if not root or not humanoid or humanoid.Health <= 0 then
							return
						end
						local npcs = workspace:FindFirstChild("NPCs")
						local hawkEye = npcs and (npcs:FindFirstChild("Hawk Eye") or npcs:FindFirstChild("Mihawk"))
						local hawkRoot = hawkEye and (hawkEye:FindFirstChild("HumanoidRootPart") or hawkEye.PrimaryPart)
						if hawkRoot and (hawkRoot.Position - root.Position).Magnitude <= 120 then
							lastDodge = tick()
							getgenv().HawkEyeDodging = tick()
							local target = hawkRoot.CFrame * CFrame.new(0, 15, 18)
							local events = game:GetService("ReplicatedStorage"):FindFirstChild("Events")
							local takestam = events and events:FindFirstChild("takestam")
							if takestam then
								takestam:FireServer(0.505, "dash", target)
							end
							root.CFrame = target
							root.AssemblyLinearVelocity = Vector3.zero
						end
					end

					getgenv().mihawkWatchChild = function(child)
						if not getgenv().AutoMihawkBoss then
							return
						end
						local name = child and child.Name
						if not name then
							return
						end
						local lowered = name:lower()
						if lowered:find("yoru") or lowered:find("giant") or lowered:find("slice") or lowered:find("slash") or lowered:find("thousand") then
							getgenv().mihawkDodge()
						end
					end

					do
						local KEY = "F3.MihawkWatch"
						local token = {}
						loops[KEY] = token
						local watched = nil
						local connection = nil
						task.spawn(function()
							task.wait()
							while task.wait(1) do
								if loops[KEY] ~= token then
									if connection then
										pcall(function()
											connection:Disconnect()
										end)
									end
									break
								end
								local g = getgenv()
								if g.AutoMihawkBoss and g.MihawkChildDodge ~= false then
									local npcs = workspace:FindFirstChild("NPCs")
									local hawkEye = npcs and (npcs:FindFirstChild("Hawk Eye") or npcs:FindFirstChild("Mihawk"))
									if hawkEye ~= watched then
										if connection then
											pcall(function()
												connection:Disconnect()
											end)
											connection = nil
										end
										watched = hawkEye
										if hawkEye then
											for _, child in ipairs(hawkEye:GetChildren()) do
												getgenv().mihawkWatchChild(child)
											end
											connection = hawkEye.ChildAdded:Connect(function(child)
												getgenv().mihawkWatchChild(child)
											end)
										end
									end
								end
							end
						end)
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 30_BossStatusText (final/missing_farm/F3/30_BossStatusText.lua) =====
				do
					-- BossStatusText(boss)  boss = "Juzo" | "Mihawk" | "Roger"  (the keys of the hub's Status paragraphs)
					-- Recovered from pool-format/batch_A11/pA1119.lua (the whole body).
					-- Returns the one-line status string the hub shows in each boss tab's "Status" paragraph ("off" when the boss toggle is off).
					-- Helper schedule functions below come from pA8969 (Roger), pA3927 (Mihawk) and pA6715 (Umi window predicate).

					-- F3 / 30_BossStatusText: replacement of final/missing/BossStatusText.lua (pA1119).  Same text, but the "killed this spawn window" flags and the
					-- schedule/Umi-window helpers are the real shared ones (00_BossState.lua), so the farm loop's rogerDone / mihawkDone show up in the status line.
					-- This file is spliced after final/missing/, so this definition of getgenv().BossStatusText is the one that stays.

					local Players = game:GetService("Players")
					local localPlayer = Players.LocalPlayer -- pA1119 upv1: only ever used as `upv1.Character` CONFIRMED

					-- pA1119 upv3 = umiBossComingUp (pA6715), upv4 = rogerSchedule (pA8969), upv5 = rogerDone, upv6 = mihawkSchedule (pA3927), upv7 = mihawkDone: CONFIRMED by the
					-- farm loop pA844, which sets the same flags and calls the same functions (see 20_BossMain.notes.md).
					local function state()
						return getgenv().__TensenBossState
					end
					local function umiBossComingUp()
						return getgenv().umiBossComingUp()
					end
					local function rogerSchedule()
						return getgenv().RogerSchedule()
					end
					local function mihawkSchedule()
						return getgenv().MihawkSchedule()
					end

					-- m:ss, pA1119's own fn (its first argument is an anti-tamper constant and is dropped)
					local function clock(seconds)
						local total = math.max(0, math.floor(seconds))
						return string.format("%d:%02d", math.floor(total / 60), total % 60)
					end

					getgenv().BossStatusText = function(boss)
						local genv = getgenv()

						if not (boss == "Juzo" and genv.AutoJuzoBoss or boss == "Roger" and genv.AutoRogerBoss or boss == "Mihawk" and genv.AutoMihawkBoss) then
							return "off"
						end

						if game.PlaceId ~= 7465136166 then
							return "only works in Second Sea"
						end

						if genv.BossFarmDisabled then
							return "held off - BossFarmDisabled is set"
						end

						local paused = genv.AutoFishing

						if not paused then
							paused = genv.AutoMerchant
						end

						if paused then
							return "paused - Auto Fishing or Auto Merchant is on"
						end

						local label = boss == "Juzo" and "Juzo" or boss == "Roger" and "Roger" or "Mihawk"
						local npcName = boss == "Juzo" and "Juzo the Diamondback" or boss == "Roger" and "Roger" or "Hawk Eye"
						local character = localPlayer.Character
						local rootPart = character and character:FindFirstChild("HumanoidRootPart")
						local npcs = workspace:FindFirstChild("NPCs")
						local bossModel = npcs and npcs:FindFirstChild(npcName)
						local bossHumanoid = bossModel and bossModel:FindFirstChildOfClass("Humanoid")
						local bossRoot = bossModel and (bossModel:FindFirstChild("HumanoidRootPart") or bossModel.PrimaryPart)
						local bossAlive = bossHumanoid and bossRoot and bossHumanoid.Health > 0

						-- pA1119 fn2: "fighting ..." line. Its upvalues: rootPart, bossRoot, genv, bossModel, <name>, bossHumanoid, label.
						local function fightingLine()
							local studs = rootPart and (rootPart.Position - bossRoot.Position).Magnitude or -1
							local blocking = genv.bossTargetBlocking and genv.bossTargetBlocking(bossModel)

							-- BINDING INFERRED: the %s name is a separate upvalue from `label` (which is the config-key prefix); npcName and `boss` are the
							-- two candidates. npcName chosen. Cosmetic only.
							return string.format(
								"fighting %s - %d studs away - HP %d/%d%s",
								npcName,
								math.floor(studs),
								math.floor(bossHumanoid.Health),
								math.floor(bossHumanoid.MaxHealth),
								blocking and (genv[label .. "FeintOnBlock"] ~= false and " - blocking so fake m1" or " - blocking") or ""
							)
						end

						if boss == "Juzo" then
							if bossAlive and genv.JuzoFighting then
								return fightingLine()
							end

							if genv.BossLootDwelling and not bossAlive then
								return "Juzo is down - picking up the loot"
							end

							if (genv.AutoRogerBoss or genv.AutoMihawkBoss) and (umiBossComingUp() or genv.UmiBossEngaged) then
								return "waiting - Roger/Mihawk is up first"
							end

							local studs

							if rootPart then
								studs = (rootPart.Position - Vector3.new(1770.34546, 36.0756149, -10659.0898)).Magnitude
							end

							studs = studs or 0

							if studs > 150 then
								return string.format("heading to Juzo's island (%d studs)", math.floor(studs))
							end

							return "at Juzo's island - waiting for him to spawn"
						end

						local untilOpen, intoCycle, windowOpen, done

						if boss == "Roger" then
							untilOpen, intoCycle, windowOpen = rogerSchedule()
							done = state().rogerDone
						else
							untilOpen, intoCycle, windowOpen = mihawkSchedule()
							done = state().mihawkDone
						end

						if bossAlive and genv.UmiBossEngaged then
							return fightingLine()
						end

						if genv.BossLootDwelling and not bossAlive then
							return label .. " is down - picking up the loot"
						end

						local studs

						if rootPart then
							studs = (rootPart.Position - Vector3.new(12642.7695, 144.162933, 2898.39746)).Magnitude
						end

						studs = studs or 0

						if windowOpen then
							if done then
								return string.format("%s is done this cycle - next spawn in %s", label, clock(boss == "Roger" and 5400 - intoCycle or 7200 - intoCycle))
							end

							if studs > 150 then
								return string.format("%s is up - heading to Umi (%d studs)", label, math.floor(studs))
							end

							return string.format("at Umi - waiting for %s (window closes in %s)", label, clock(900 - intoCycle))
						end

						if untilOpen <= 180 then
							if studs > 150 then
								return string.format("%s spawns in %s - heading to Umi (%d studs)", label, clock(untilOpen), math.floor(studs))
							end

							return string.format("at Umi - %s spawns in %s", label, clock(untilOpen))
						end

						return string.format("waiting - %s spawns in %s", label, clock(untilOpen))
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 10_ScrollHelpers (final/missing_farm/F4/10_ScrollHelpers.lua) =====
				do
					-- F4 / 10_ScrollHelpers: the helper functions behind "Auto Get Scroll" (getgenv().AutoWorldScroll, Lvl 325+, First Sea).
					-- Every function is the lifted body of one per-proto lift (pool-format/batch_A11/pA<key>.lua), junk removed, upvalues bound by reading the code.
					-- Shared with the loop file (20_AutoScrollLoop.lua) through getgenv().__TensenF4 (this file is wrapped in its own do ... end by the splice).
					--
					--   pA6275 isAlive          pA9658 rawScrollCount      pA4811 scrollCount (cached)   pA2707 ScrollNeeded      pA679 levelOk       pA10102 ScrollEligible
					--   pA3762 ScrollHoldLive   pA4715 holdKey             pA4176 sendKey                pA7998 findScroll        pA842 grabRange     pA2347 findPrompt
					--   pA11269 basePartOf      pA10486 scrollPickable     pA3788 pickUpScroll           pA3691 atCamp            pA10022 moveOnto    pA8563 TweenToWorldScroll
					--   pA6324 Level (shared fallback, only installed when nobody else defined getgenv().Level)

					local Players = game:GetService("Players")
					local ReplicatedStorage = game:GetService("ReplicatedStorage")
					local HttpService = game:GetService("HttpService")
					local localPlayer = Players.LocalPlayer

					local F4 = getgenv().__TensenF4
					if not F4 then
						F4 = {}
						getgenv().__TensenF4 = F4
					end

					-- First Sea place id (the place the toggle is documented for: "Lvl 325+, First Sea"; the Kaitun loop pA2586 breaks out of any other place with the same id).
					-- INFERRED for the loop gate (pA3358 upvalue 1 / pA10102 upvalue 1): the gate is silent in the lift, the id is the one the status text (pA5353) uses for "First Sea".
					local FIRST_SEA = 3978370137

					function F4.log(message)
						local fn = getgenv().BMLog
						if type(fn) == "function" then
							pcall(fn, message)
						else
							print(message)
						end
					end

					-- pA6324: Level() = the number in HUD.Main.Bars.Experience.Detail.Level (nil when the HUD is not up). Installed only when nobody defined it.
					if type(getgenv().Level) ~= "function" then
						getgenv().Level = function()
							local gui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
							local hud = gui and gui:FindFirstChild("HUD")
							local main = hud and hud:FindFirstChild("Main")
							local bars = main and main:FindFirstChild("Bars")
							local experience = bars and bars:FindFirstChild("Experience")
							local detail = experience and experience:FindFirstChild("Detail")
							local level = detail and detail:FindFirstChild("Level")
							if not level then
								return nil
							end
							return (tonumber(level.Text:match("%d+")))
						end
					end

					local function currentLevel()
						local fn = getgenv().Level
						if type(fn) ~= "function" then
							return nil
						end
						local ok, value = pcall(fn)
						return ok and value or nil
					end

					-- pA6275: character, Humanoid alive, HumanoidRootPart present
					function F4.isAlive()
						local character = localPlayer.Character
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						local root = character and character:FindFirstChild("HumanoidRootPart")
						return (humanoid and humanoid.Health > 0 and root ~= nil and true) or false
					end

					-- pA9658: World Scrolls in the bag. Stats<Name>.Inventory.Inventory is a JSON string of {item = count}.
					-- Binding: upvalue 1 = ReplicatedStorage, upvalue 2 = LocalPlayer, upvalue 4 = HttpService (JSONDecode). INFERRED, strong: pA903 (hasBusoHaki) uses the same
					-- `upvN:FindFirstChild("Stats" .. LocalPlayer.Name)` and the FarmStatusText notes confirm ReplicatedStorage for it.
					local function rawScrollCount()
						local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
						local inventory = stats and stats:FindFirstChild("Inventory")
						inventory = inventory and inventory:FindFirstChild("Inventory")
						if not inventory then
							return 0
						end
						local value = inventory.Value
						if not value or value == "" then
							return 0
						end
						local ok, result = pcall(function()
							return HttpService:JSONDecode(value)
						end)
						if not ok or type(result) ~= "table" then
							return 0
						end
						return tonumber(result["World Scroll"]) or 0
					end

					-- pA4811: the same count with a cache (getgenv().ScrollCountCache seconds, default 1 = constant 68). INFERRED: the cache starts at -1 / time 0 (the lift tests `cached >= 0`).
					local cachedCount, cachedAt = -1, 0
					local function scrollCount()
						if cachedCount >= 0 and tick() - cachedAt < (getgenv().ScrollCountCache or 1) then
							return cachedCount
						end
						local value = rawScrollCount()
						cachedCount = value
						cachedAt = tick()
						return cachedCount
					end
					F4.scrollCount = scrollCount
					if getgenv().WorldScrollCount == nil then
						getgenv().WorldScrollCount = scrollCount
					end

					-- pA2707: still need a scroll?
					local function scrollNeeded()
						return scrollCount() < (tonumber(getgenv().ScrollWantCount) or 1)
					end
					F4.scrollNeeded = scrollNeeded
					if getgenv().ScrollNeeded == nil then
						getgenv().ScrollNeeded = scrollNeeded
					end

					-- pA679: level gate (getgenv().ScrollMinLevel, default 325; <= 0 disables it)
					local function levelOk()
						local minLevel = getgenv().ScrollMinLevel or 325
						if minLevel <= 0 then
							return true
						end
						return (currentLevel() or 0) >= minLevel
					end
					F4.levelOk = levelOk

					local function placeOk()
						return game.PlaceId == FIRST_SEA
					end
					F4.placeOk = placeOk

					-- pA10102: the whole gate in one call (toggle on + First Sea + level + still needed)
					local function scrollEligible()
						return getgenv().AutoWorldScroll == true and placeOk() and levelOk() and scrollNeeded()
					end
					F4.scrollEligible = scrollEligible
					if getgenv().ScrollEligible == nil then
						getgenv().ScrollEligible = scrollEligible
					end

					-- pA3762: a grab is running and its heartbeat is fresh (getgenv().ScrollStaleMax seconds, default 10). Called by the auto farm loop (pA2890) and the fruit store (pA6588).
					local function scrollHoldLive()
						if getgenv().ScrollHold ~= true then
							return false
						end
						if getgenv().GettingScroll ~= true then
							return false
						end
						return tick() - (getgenv().ScrollHeartbeat or 0) < (getgenv().ScrollStaleMax or 10)
					end
					F4.scrollHoldLive = scrollHoldLive
					getgenv().ScrollHoldLive = scrollHoldLive

					-- pA4715: the key held to pick the scroll up (getgenv().ScrollHoldKey as an Enum.KeyCode, default LeftAlt)
					local function holdKey()
						local key = getgenv().ScrollHoldKey
						if typeof(key) == "EnumItem" then
							return key
						end
						return Enum.KeyCode.LeftAlt
					end

					-- pA4176: press / release a key through VirtualInputManager
					local function sendKey(key, down)
						pcall(function()
							game:GetService("VirtualInputManager"):SendKeyEvent(down, key, false, game)
						end)
					end

					-- pA7998: the world scroll instance (workspace.Effects["World Scroll"], else workspace["World Scroll"])
					local function findScroll()
						local effects = workspace:FindFirstChild("Effects")
						local worldScroll = effects and effects:FindFirstChild("World Scroll")
						if worldScroll then
							return worldScroll
						end
						return workspace:FindFirstChild("World Scroll")
					end
					F4.findScroll = findScroll

					-- pA842: how close you have to be (getgenv().ScrollRange, default 18 = constant 18; capped by the prompt's MaxActivationDistance)
					local function grabRange(prompt)
						local range = getgenv().ScrollRange or 18
						if prompt then
							pcall(function()
								local maxActivationDistance = prompt.MaxActivationDistance
								if maxActivationDistance and maxActivationDistance > 0 then
									range = math.min(range, maxActivationDistance)
								end
							end)
						end
						return range
					end

					-- pA2347: the ProximityPrompt of an instance (itself or the first descendant)
					local function findPrompt(instance)
						if not instance then
							return nil
						end
						if instance:IsA("ProximityPrompt") then
							return instance
						end
						local prompt = nil
						pcall(function()
							prompt = instance:FindFirstChildWhichIsA("ProximityPrompt", true)
						end)
						return prompt
					end

					-- pA11269: a BasePart to measure against (the instance itself, else its first BasePart descendant).
					-- INFERRED binding for pA10486 upvalue 3 / pA10022 upvalue 1 (both call it with the scroll and read `.Position`; pA2378 returns a Vector3 and pA3735 a part too,
					-- but pA11269 is the one that searches descendants first-come like the neighbouring helpers).
					local function basePartOf(instance)
						if not instance then
							return nil
						end
						if instance:IsA("BasePart") then
							return instance
						end
						for _, descendant in ipairs(instance:GetDescendants()) do
							if descendant:IsA("BasePart") then
								return descendant
							end
						end
						return nil
					end
					F4.basePartOf = basePartOf

					-- pA10486: can the scroll be grabbed right now?  returns ok, reason, gone
					local function scrollPickable()
						local effects = workspace:FindFirstChild("Effects")
						local worldScroll = effects and effects:FindFirstChild("World Scroll")
						if not worldScroll or not worldScroll.Parent then
							return false, "no scroll in the world", true
						end
						local prompt = worldScroll:FindFirstChild("ProximityPrompt") or findPrompt(worldScroll)
						if not prompt then
							return false, "the scroll has no prompt", false
						end
						local active = true
						pcall(function()
							if prompt.Enabled == false then
								active = false
							end
						end)
						if not active then
							return false, "the prompt is not active yet", false
						end
						local part = basePartOf(worldScroll)
						local character = localPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						if not part or not root then
							return false, "cannot tell how far the scroll is", false
						end
						local distance = (part.Position - root.Position).Magnitude
						if distance > grabRange(prompt) then
							return false, string.format("too far to grab it (%d studs)", math.floor(distance)), false
						end
						return true, nil, false
					end
					F4.scrollPickable = scrollPickable

					-- pA3788: hold the key on the scroll until the bag count goes up.  returns true when a scroll was taken
					local function pickUpScroll()
						local pickable, blockReason = scrollPickable()
						if not pickable then
							getgenv().ScrollBlockReason = blockReason
							return false
						end
						local before = scrollCount()
						local key = holdKey()
						local holdSeconds = tonumber(getgenv().ScrollHoldSeconds) or 5
						getgenv().ScrollBlockReason = "holding ALT to pick it up"
						local tries = getgenv().ScrollFireTries or 12
						for _ = 1, tries do
							if not getgenv().AutoWorldScroll then
								break
							end
							if not F4.isAlive() then
								sendKey(key, false)
								getgenv().ScrollBlockReason = "died before grabbing it"
								return false
							end
							local stillPickable, reason, gone = scrollPickable()
							if not stillPickable then
								sendKey(key, false)
								task.wait(0.5)
								if before < scrollCount() then
									getgenv().ScrollsTaken = (getgenv().ScrollsTaken or 0) + 1
									getgenv().ScrollBlockReason = "got the scroll"
									return true
								end
								getgenv().ScrollBlockReason = gone and "someone else took it" or reason
								return false
							end
							sendKey(key, true)
							local deadline = tick() + holdSeconds
							while true do
								getgenv().ScrollHeartbeat = tick()
								task.wait(0.25)
								if before < scrollCount() then
									break
								end
								if not (tick() >= deadline) and getgenv().AutoWorldScroll and F4.isAlive() then
									continue
								end
								break
							end
							sendKey(key, false)
							if scrollCount() > before then
								getgenv().ScrollsTaken = (getgenv().ScrollsTaken or 0) + 1
								getgenv().ScrollBlockReason = "got the scroll"
								return true
							end
							task.wait(0.25)
						end
						sendKey(key, false)
						getgenv().ScrollFails = (getgenv().ScrollFails or 0) + 1
						getgenv().ScrollBlockReason = "holding ALT gave nothing"
						return false
					end
					F4.pickUpScroll = pickUpScroll

					-- pA3691: standing within ScrollCampRange studs (setting on getgenv(), default 25 = constant 189) of the camp spot WorldScrollCF
					local function atCamp()
						local character = localPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local campCF = getgenv().WorldScrollCF
						if not root or not campCF then
							return false
						end
						return (campCF.Position - root.Position).Magnitude <= (getgenv().ScrollCampRange or 25)
					end
					F4.atCamp = atCamp

					-- pA10022: tween onto an instance (stops short by 4 studs, teleports when within 5).  No-op while another tween runs.
					-- Binding: upvalue 2 = the hub tween state (E9 rewrites the nil placeholder below).
					local tweenState = getgenv().__TensenTweenState   -- bound to the hub tween-state table (E9a)
					local function moveOnto(instance)
						local part = basePartOf(instance)
						if not part then
							return
						end
						local state = tweenState or getgenv().__TensenTweenState
						if state and state.Enabled then
							return
						end
						local tween = getgenv().TweenToCFrame
						if type(tween) ~= "function" then
							return
						end
						pcall(tween, {
							CFrame = CFrame.new(part.Position),
							Speed = getgenv().TweenSpeedMaster or 110,
							StopDistance = 4,
							TeleportOnClose = true,
							TeleportDistance = 5,
						})
					end
					F4.moveOnto = moveOnto

					-- pA8563: travel to the camp spot.  getgenv().WorldScrollCF is set outside the lifted protos (a constant of the lost loader region); see the notes.
					local function tweenToWorldScroll()
						local tween = getgenv().TweenToCFrame
						if type(tween) ~= "function" or not getgenv().WorldScrollCF then
							return
						end
						tween({
							CFrame = getgenv().WorldScrollCF,
							Speed = getgenv().TweenSpeedMaster or 110,
							StopDistance = 5,
							TeleportOnClose = true,
							TeleportDistance = 5,
						})
					end
					if getgenv().TweenToWorldScroll == nil then
						getgenv().TweenToWorldScroll = tweenToWorldScroll
					end
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 20_AutoScrollLoop (final/missing_farm/F4/20_AutoScrollLoop.lua) =====
				do
					-- F4 / 20_AutoScrollLoop: the "Auto Get Scroll" thread (getgenv().AutoWorldScroll, Lvl 325+, First Sea) = lifted proto pA3358.
					-- Camps the World Scroll spot, pauses the other farms while it waits (they acknowledge through ScrollAckFarm / ScrollAckFish), walks onto the scroll the moment it
					-- spawns and holds ALT on it until the bag count goes up.  Helpers: 10_ScrollHelpers.lua (shared through getgenv().__TensenF4).
					--
					-- Binding table (pA3358 upvalues):  1 first-sea gate | 2 level gate pA679 | 3 scroll needed pA2707 | 4 alive pA6275 | 5 constants (73 = 15 s ack wait, 197 = 0.2 s, 11 = false)
					--   6 scroll eligible pA10102 (toggle + First Sea + level + still needed: the loop ends when the scroll is in the bag; ScrollHoldLive pA3762 is only for the OTHER loops) | 7 hub tween state | 8 hub StopCurrentTween | 9 findScroll pA7998 | 10 scrollPickable pA10486 | 11 pickUpScroll pA3788
					--   12 moveOnto pA10022 | 13 atCamp pA3691 | the free global TweenToWorldScroll = pA8563

					local F4 = getgenv().__TensenF4
					local loops = getgenv().__TensenFarmLoops
					if not loops then
						loops = {}
						getgenv().__TensenFarmLoops = loops
					end

					local tweenState = getgenv().__TensenTweenState   -- bound to the hub tween-state table (E9a)               -- E9 binds this to the hub tween-state table
					local stopTween = getgenv().StopCurrentTween   -- hub tween stop (E9a)                -- E9 binds this to the hub tween stop function

					local function tween()
						return tweenState or getgenv().__TensenTweenState
					end

					local function stop()
						local fn = stopTween or getgenv().StopCurrentTween
						if type(fn) == "function" then
							pcall(fn)
						end
					end

					-- ADDED (not in the lifted proto): the camp spot constant getgenv().WorldScrollCF lives in the lost loader region and could not be recovered.  Until it is set
					-- (by the user, or by a later recovery), remember the place the first scroll shows up at so the "camp the spot" half of the loop has somewhere to go.
					-- Turn off with getgenv().ScrollLearnSpot = false.
					local function learnSpot(scroll)
						if getgenv().WorldScrollCF ~= nil or getgenv().ScrollLearnSpot == false then
							return
						end
						local part = F4.basePartOf(scroll)
						if part then
							getgenv().WorldScrollCF = CFrame.new(part.Position)
							F4.log("[Scroll] no camp spot recorded - using the place the scroll spawned at: " .. tostring(part.Position))
						end
					end

					local token = {}
					loops["F4.AutoScroll"] = token

					task.spawn(function()
						task.wait()
						while task.wait(getgenv().ScrollRate or 2) do
							if loops["F4.AutoScroll"] ~= token then
								break
							end
							local ok, err = pcall(function()
								if getgenv().GettingScroll then
									return
								end

								if not getgenv().AutoWorldScroll then
									return
								end

								if not F4.placeOk() then
									return
								end

								if not F4.levelOk() then
									getgenv().ScrollBlockReason = "level is too low"
								elseif not F4.scrollNeeded() then
									getgenv().ScrollBlockReason = "you already have a scroll"
								else
									if not F4.isAlive() then
										return
									end

									getgenv().ScrollHeartbeat = tick()
									getgenv().GettingScroll = true
									getgenv().ScrollHold = true
									getgenv().ScrollCampStart = tick()
									getgenv().ScrollBlockReason = "pausing the other farms"
									local waitStart = tick()

									-- wait until the farms that run acknowledge the pause (or ScrollAckWait / 15 s pass, or the grab is no longer wanted)
									repeat
										getgenv().ScrollHeartbeat = tick()
										task.wait(0.1)
									until ((not getgenv().autofarm or getgenv().ScrollAckFarm) and (not getgenv().AutoFishing or getgenv().ScrollAckFish) or tick() - waitStart > (getgenv().ScrollAckWait or 15))
										or not F4.scrollEligible()

									if tween().Enabled then
										stop()
									end

									if getgenv().EndFishingSession then
										pcall(getgenv().EndFishingSession)
									end

									task.wait(0.2)

									while F4.scrollEligible() do
										getgenv().ScrollHeartbeat = tick()

										if not F4.isAlive() then
											getgenv().ScrollBlockReason = "waiting to respawn"

											if tween().Enabled then
												stop()
											end

											task.wait(1)
											continue
										end

										local scroll = F4.findScroll()

										if scroll and F4.scrollPickable() then
											if tween().Enabled then
												stop()
											end

											learnSpot(scroll)
											pcall(F4.pickUpScroll)
											task.wait(getgenv().ScrollCampRate or 0.5)
										elseif scroll then
											getgenv().ScrollBlockReason = "a scroll is out - moving onto it"
											learnSpot(scroll)
											F4.moveOnto(scroll)
											task.wait(getgenv().ScrollCampRate or 0.5)
										else
											if F4.atCamp() then
												getgenv().ScrollBlockReason = "camping the spot - no scroll yet"
												task.wait(getgenv().ScrollCampRate or 0.5)
												continue
											end

											getgenv().ScrollBlockReason = "heading to the scroll spot"

											if not tween().Enabled then
												pcall(getgenv().TweenToWorldScroll)
											end

											local travelStart = tick()

											repeat
												getgenv().ScrollHeartbeat = tick()
												task.wait(0.25)
											until not (not (F4.atCamp() or F4.findScroll()) and tween().Enabled and F4.isAlive() and not (tick() - travelStart > (getgenv().ScrollTravelMax or 45)) and F4.scrollEligible())

											if F4.atCamp() and tween().Enabled then
												stop()
											end

											task.wait(0.2)
										end
									end

									if tween().Enabled then
										stop()
									end

									if not F4.scrollNeeded() then
										getgenv().ScrollBlockReason = "got the scroll - back to farming"
									end

									getgenv().GettingScroll = false
									getgenv().ScrollHold = false
									getgenv().ScrollHeartbeat = 0
									getgenv().AlreadyTweenFishing = false
								end
							end)

							if not ok then
								-- a failed step must not leave the other farms paused behind a dead grab
								getgenv().GettingScroll = false
								getgenv().ScrollHold = false
								getgenv().ScrollHeartbeat = 0
								if getgenv().BMLog and os.clock() - (getgenv().__F4LastLoopErr or 0) > 10 then
									getgenv().__F4LastLoopErr = os.clock()
									getgenv().BMLog("[F4] auto scroll step failed: " .. tostring(err))
								end
							end
						end
					end)
				end

				-- ===== RECOVERED FROM PER-PROTO LIFT: 30_HakiHelpers (final/missing_farm/F4/30_HakiHelpers.lua) =====
				do
					-- F4 / 30_HakiHelpers: the helper functions behind "Auto Haki" (getgenv().haki = "Auto Haki (Lvl 80+) and 25k peli": the Yeti quest "Road to Armament" that unlocks Buso Haki).
					-- Each function is the lifted body of one per-proto lift (pool-format/batch_A11/pA<key>.lua), junk removed, upvalues bound by reading the code.
					--
					--   pA903 hasBusoHaki      pA2576 getPeli        pA11506 IsOnYetiQuest      pA6271 HakiTravelReady
					--   pA2676 TweenToYetiSafePlace (CFrame -4253.1, 169.5, -2957.5)            pA8889 TweenToHaki (CFrame -4248.2, 169.5, -2992.0)
					-- Shared with 40_AutoHakiLoop.lua through getgenv().__TensenF4.

					local Players = game:GetService("Players")
					local ReplicatedStorage = game:GetService("ReplicatedStorage")
					local localPlayer = Players.LocalPlayer

					local F4 = getgenv().__TensenF4
					if not F4 then
						F4 = {}
						getgenv().__TensenF4 = F4
					end
					if not F4.log then
						function F4.log(message)
							local fn = getgenv().BMLog
							if type(fn) == "function" then
								pcall(fn, message)
							else
								print(message)
							end
						end
					end

					local function playerGui()
						return localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
					end

					-- pA903: does the player own Buso Haki?  Looks in Stats<Name>.Skills / Stats<Name>.Stats, then the character, then the HUD.
					-- Binding: upvalue 1 = ReplicatedStorage (the same `Stats<Name>` container pA9658 uses), upvalue 2 = LocalPlayer, upvalues 4 / 5 = the two HUD containers.
					-- INFERRED for 4 / 5: the lift looks up `HUD` first in one container and falls back to a second; PlayerGui is where the HUD lives (pA2576, pA6324), the fallback is
					-- bound to LocalPlayer (harmless: it can only find a HUD child of the player).
					local function hasBusoHaki()
						local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

						if stats then
							local skills = stats:FindFirstChild("Skills")

							if skills then
								for _, name in ipairs({ "busoHaki", "BusoHaki", "buso", "Buso", "haki", "Haki", "busoshokuHaki", "BusoshokuHaki" }) do
									local skill = skills:FindFirstChild(name)

									if skill then
										skill = skill.Value == true or skill.Value == 1 or type(skill.Value) == "number" and skill.Value > 0
									end

									if skill then
										return true
									end
								end
							end

							local inner = stats:FindFirstChild("Stats")

							if inner then
								local buso = inner:FindFirstChild("Buso") or inner:FindFirstChild("buso")

								if buso then
